/************************************內部建置************************************************/
DELETE FROM DS_SEC.CF_ASSET1 WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_ASSET2 WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_ASSET3 WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_ASSET4 WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_ACTUBNF WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_ACTUBNFROI WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_INVBNF WHERE YYYYMM = :ym;
DELETE FROM DS_SEC.CF_INVBNFROI WHERE YYYYMM = :ym;

CREATE TABLE TEMP5ACTUBNF
AS
SELECT PARTY_ID_MASK AS PARTY_ID
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE = 'USD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)USD_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE NOT IN('USD','TWD') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)OD_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '110' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)ST_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('150','450') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BSBL_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '160' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)LOAN_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '210' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FS_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN('120','220','420') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FD_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '230' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FB_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN('540','240') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)SN_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '6L0' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_ACTUBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FU_ACTUBNF_M
          
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE = 'USD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)USD_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE NOT IN('USD','TWD') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)OD_ACTUBNF_L      
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '110' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)ST_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('150','450') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BSBL_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '160' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)LOAN_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '210' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FS_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN('120','220','420') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FD_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '230' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FB_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)SN_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_ACTUBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FU_ACTUBNF_L
           
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND CURRENCY_CODE = 'USD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)USD_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND CURRENCY_CODE NOT IN('USD','TWD') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)OD_ACTUBNF_3M      
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '110' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)ST_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('150','450') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BSBL_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '160' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)LOAN_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '210' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FS_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN('120','220','420') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FD_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '230' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FB_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN('540','240') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)SN_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '6L0' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_ACTUBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FU_ACTUBNF_3M
      
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND CURRENCY_CODE = 'USD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)USD_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND CURRENCY_CODE NOT IN('USD','TWD') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)OD_ACTUBNF_3ML      
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE = '110' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)ST_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('150','450') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BSBL_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE = '160' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)LOAN_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE = '210' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FS_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN('120','220','420') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FD_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE = '230' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FB_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)SN_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_ACTUBNF_3ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FU_ACTUBNF_3ML
      
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND CURRENCY_CODE = 'USD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)USD_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND CURRENCY_CODE NOT IN('USD','TWD') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)OD_ACTUBNF_6M      
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '110' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)ST_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('150','450') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BSBL_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '160' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)LOAN_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '210' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FS_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN('120','220','420') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FD_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '230' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FB_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN('540','240') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)SN_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE = '6L0' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_ACTUBNF_6M
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FU_ACTUBNF_6M

      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)AP_ACTUBNF_6ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)BR_ACTUBNF_6ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)FP_ACTUBNF_6ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN ACTU_BENEFIT_AMT_TWD ELSE 0 END)TWD_ACTUBNF_6ML
