      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '160' THEN NET_COST_AMT_TWD ELSE 0 END)LOAN_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '210' THEN NET_COST_AMT_TWD ELSE 0 END)FS_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN('120','220','420') THEN NET_COST_AMT_TWD ELSE 0 END)FD_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '230' THEN NET_COST_AMT_TWD ELSE 0 END)FB_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN NET_COST_AMT_TWD ELSE 0 END)SN_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN NET_COST_AMT_TWD ELSE 0 END)INSURANCE_NET_COST_12ML
      ,SUM(CASE WHEN SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN NET_COST_AMT_TWD ELSE 0 END)FU_NET_COST_12ML
FROM DM_S_VIEW.M_AC_ACCOUNT_ACTU_BENEFIT A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
WHERE SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -23), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK;
/************************************對外輸出************************************************/
INSERT INTO DS_SEC.CF_ACTUBNF
SELECT A.CUSTOMER_ID 
      ,A.YYYYMM
      ,ROUND(AP_ACTUBNF_M,0) AP_ACTUBNF_M
      ,ROUND(BR_ACTUBNF_M,0) BR_ACTUBNF_M
      ,ROUND(FP_ACTUBNF_M,0) FP_ACTUBNF_M
      ,ROUND(TWD_ACTUBNF_M,0) TWD_ACTUBNF_M
      ,ROUND(USD_ACTUBNF_M,0) USD_ACTUBNF_M
      ,ROUND(OD_ACTUBNF_M,0) OD_ACTUBNF_M
