      ,ROUND(CASE WHEN NVL(FP_ACTUBNF_M,0) = 0 AND NVL(FP_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(FP_ACTUBNF_M,0) - NVL(FP_ACTUBNF_L,0) END,0) AS FP_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(TWD_ACTUBNF_M,0) = 0 AND NVL(TWD_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(TWD_ACTUBNF_M,0) - NVL(TWD_ACTUBNF_L,0) END,0) AS TWD_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(USD_ACTUBNF_M,0) = 0 AND NVL(USD_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(USD_ACTUBNF_M,0) - NVL(USD_ACTUBNF_L,0) END,0) AS USD_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(OD_ACTUBNF_M,0) = 0 AND NVL(OD_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(OD_ACTUBNF_M,0) - NVL(OD_ACTUBNF_L,0) END,0) AS OD_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(ST_ACTUBNF_M,0) = 0 AND NVL(ST_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(ST_ACTUBNF_M,0) - NVL(ST_ACTUBNF_L,0) END,0) AS ST_ACTUBNF_M_MDIFF 
