      ,ROUND(CASE WHEN NVL(FS_ACTUBNF_M,0) = 0 AND NVL(FS_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(FS_ACTUBNF_M,0) - NVL(FS_ACTUBNF_L,0) END,0) AS FS_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FD_ACTUBNF_M,0) = 0 AND NVL(FD_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(FD_ACTUBNF_M,0) - NVL(FD_ACTUBNF_L,0) END,0) AS FD_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FB_ACTUBNF_M,0) = 0 AND NVL(FB_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(FB_ACTUBNF_M,0) - NVL(FB_ACTUBNF_L,0) END,0) AS FB_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(SN_ACTUBNF_M,0) = 0 AND NVL(SN_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(SN_ACTUBNF_M,0) - NVL(SN_ACTUBNF_L,0) END,0) AS SN_ACTUBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FU_ACTUBNF_M,0) = 0 AND NVL(FU_ACTUBNF_L,0) = 0 THEN NULL ELSE NVL(FU_ACTUBNF_M,0) - NVL(FU_ACTUBNF_L,0) END,0) AS FU_ACTUBNF_M_MDIFF
      
      ,ROUND(CASE WHEN NVL(AP_ACTUBNF_L,0)!=0 THEN (NVL(AP_ACTUBNF_M,0)/NVL(AP_ACTUBNF_L,0))-1 ELSE NULL END,4) AS AP_ACTUBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(BR_ACTUBNF_L,0)!=0 THEN (NVL(BR_ACTUBNF_M,0)/NVL(BR_ACTUBNF_L,0))-1 ELSE NULL END,4) AS BR_ACTUBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FP_ACTUBNF_L,0)!=0 THEN (NVL(FP_ACTUBNF_M,0)/NVL(FP_ACTUBNF_L,0))-1 ELSE NULL END,4) AS FP_ACTUBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(TWD_ACTUBNF_L,0)!=0 THEN (NVL(TWD_ACTUBNF_M,0)/NVL(TWD_ACTUBNF_L,0))-1 ELSE NULL END,4) AS TWD_ACTUBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(USD_ACTUBNF_L,0)!=0 THEN (NVL(USD_ACTUBNF_M,0)/NVL(USD_ACTUBNF_L,0))-1 ELSE NULL END,4) AS USD_ACTUBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(OD_ACTUBNF_L,0)!=0 THEN (NVL(OD_ACTUBNF_M,0)/NVL(OD_ACTUBNF_L,0))-1 ELSE NULL END,4) AS OD_ACTUBNF_M_RDIFF
