      ,ROUND(CASE WHEN NVL(BR_ACTUBNF_3M,0) = 0 AND NVL(BR_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(BR_ACTUBNF_3M,0) - NVL(BR_ACTUBNF_3ML,0) END,0) AS BR_ACTUBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FP_ACTUBNF_3M,0) = 0 AND NVL(FP_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(FP_ACTUBNF_3M,0) - NVL(FP_ACTUBNF_3ML,0) END,0) AS FP_ACTUBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(TWD_ACTUBNF_3M,0) = 0 AND NVL(TWD_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(TWD_ACTUBNF_3M,0) - NVL(TWD_ACTUBNF_3ML,0) END,0) AS TWD_ACTUBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(USD_ACTUBNF_3M,0) = 0 AND NVL(USD_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(USD_ACTUBNF_3M,0) - NVL(USD_ACTUBNF_3ML,0) END,0) AS USD_ACTUBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(OD_ACTUBNF_3M,0) = 0 AND NVL(OD_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(OD_ACTUBNF_3M,0) - NVL(OD_ACTUBNF_3ML,0) END,0) AS OD_ACTUBNF_3M_MDIFF
