      ,ROUND(CASE WHEN NVL(FS_ACTUBNF_3M,0) = 0 AND NVL(FS_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(FS_ACTUBNF_3M,0) - NVL(FS_ACTUBNF_3ML,0) END,0) AS FS_ACTUBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FD_ACTUBNF_3M,0) = 0 AND NVL(FD_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(FD_ACTUBNF_3M,0) - NVL(FD_ACTUBNF_3ML,0) END,0) AS FD_ACTUBNF_3M_MDIFF
