      ,ROUND(CASE WHEN NVL(FU_ACTUBNF_3M,0) = 0 AND NVL(FU_ACTUBNF_3ML,0) = 0 THEN NULL ELSE NVL(FU_ACTUBNF_3M,0) - NVL(FU_ACTUBNF_3ML,0) END,0) AS FU_ACTUBNF_3M_MDIFF
      
      ,ROUND(CASE WHEN NVL(AP_ACTUBNF_3ML,0)!=0 THEN (NVL(AP_ACTUBNF_3M,0)/NVL(AP_ACTUBNF_3ML,0))-1 ELSE NULL END,4) AS AP_ACTUBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(BR_ACTUBNF_3ML,0)!=0 THEN (NVL(BR_ACTUBNF_3M,0)/NVL(BR_ACTUBNF_3ML,0))-1 ELSE NULL END,4) AS BR_ACTUBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FP_ACTUBNF_3ML,0)!=0 THEN (NVL(FP_ACTUBNF_3M,0)/NVL(FP_ACTUBNF_3ML,0))-1 ELSE NULL END,4) AS FP_ACTUBNF_3M_RDIFF
