      ,ROUND(CASE WHEN NVL(FD_ACTUBNF_3ML,0)!=0 THEN (NVL(FD_ACTUBNF_3M,0)/NVL(FD_ACTUBNF_3ML,0))-1 ELSE NULL END,4) AS FD_ACTUBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FB_ACTUBNF_3ML,0)!=0 THEN (NVL(FB_ACTUBNF_3M,0)/NVL(FB_ACTUBNF_3ML,0))-1 ELSE NULL END,4) AS FB_ACTUBNF_3M_RDIFF
