      ,ROUND(CASE WHEN NVL(FU_ACTUBNF_6M,0) = 0 AND NVL(FU_ACTUBNF_6ML,0) = 0 THEN NULL ELSE NVL(FU_ACTUBNF_6M,0) - NVL(FU_ACTUBNF_6ML,0) END,0) AS FU_ACTUBNF_6M_MDIFF
      
