ON A.CUSTOMER_ID  = B.PARTY_ID
WHERE A.YYYYMM = :ym
;
DROP TABLE TEMP5ACTUBNF PURGE;
/************************************內部建置************************************************/
CREATE TABLE TEMP5INVBNF
AS
SELECT PARTY_ID_MASK AS PARTY_ID 
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym THEN BENEFIT_AMT_TWD ELSE 0 END)AP_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN BENEFIT_AMT_TWD ELSE 0 END)BR_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN BENEFIT_AMT_TWD ELSE 0 END)FP_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE = 'TWD' THEN BENEFIT_AMT_TWD ELSE 0 END)TWD_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE = 'USD' THEN BENEFIT_AMT_TWD ELSE 0 END)USD_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND CURRENCY_CODE NOT IN('USD','TWD') THEN BENEFIT_AMT_TWD ELSE 0 END)OD_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '110' THEN BENEFIT_AMT_TWD ELSE 0 END)ST_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('150','450') THEN BENEFIT_AMT_TWD ELSE 0 END)BSBL_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '160' THEN BENEFIT_AMT_TWD ELSE 0 END)LOAN_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '210' THEN BENEFIT_AMT_TWD ELSE 0 END)FS_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN('120','220','420') THEN BENEFIT_AMT_TWD ELSE 0 END)FD_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '230' THEN BENEFIT_AMT_TWD ELSE 0 END)FB_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN('540','240') THEN BENEFIT_AMT_TWD ELSE 0 END)SN_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE = '6L0' THEN BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_INVBNF_M
      ,SUM(CASE WHEN SNAP_YYYYMM = :ym AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN BENEFIT_AMT_TWD ELSE 0 END)FU_INVBNF_M
      
      
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') THEN BENEFIT_AMT_TWD ELSE 0 END)AP_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN BENEFIT_AMT_TWD ELSE 0 END)BR_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN BENEFIT_AMT_TWD ELSE 0 END)FP_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN BENEFIT_AMT_TWD ELSE 0 END)TWD_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE = 'USD' THEN BENEFIT_AMT_TWD ELSE 0 END)USD_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND CURRENCY_CODE NOT IN('USD','TWD') THEN BENEFIT_AMT_TWD ELSE 0 END)OD_INVBNF_L      
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '110' THEN BENEFIT_AMT_TWD ELSE 0 END)ST_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('150','450') THEN BENEFIT_AMT_TWD ELSE 0 END)BSBL_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '160' THEN BENEFIT_AMT_TWD ELSE 0 END)LOAN_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '210' THEN BENEFIT_AMT_TWD ELSE 0 END)FS_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN('120','220','420') THEN BENEFIT_AMT_TWD ELSE 0 END)FD_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '230' THEN BENEFIT_AMT_TWD ELSE 0 END)FB_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN BENEFIT_AMT_TWD ELSE 0 END)SN_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN BENEFIT_AMT_TWD ELSE 0 END)INSURANCE_INVBNF_L
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN BENEFIT_AMT_TWD ELSE 0 END)FU_INVBNF_L
      
      
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') THEN BENEFIT_AMT_TWD ELSE 0 END)AP_INVBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN BENEFIT_AMT_TWD ELSE 0 END)BR_INVBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN BENEFIT_AMT_TWD ELSE 0 END)FP_INVBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN BENEFIT_AMT_TWD ELSE 0 END)TWD_INVBNF_3M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND CURRENCY_CODE = 'USD' THEN BENEFIT_AMT_TWD ELSE 0 END)USD_INVBNF_3M
