      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN NET_COST_AMT_TWD ELSE 0 END)SN_NET_COST_6M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN NET_COST_AMT_TWD ELSE 0 END)INSURANCE_NET_COST_6M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN NET_COST_AMT_TWD ELSE 0 END)FU_NET_COST_6M
      
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') THEN NET_COST_AMT_TWD ELSE 0 END)AP_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN ('110','150','160','210','3C0','3F0','3P0') OR PROD_TYPE_CODE = '300' THEN NET_COST_AMT_TWD ELSE 0 END)BR_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN ('120','220','230','240','420','450','540','6L0')THEN NET_COST_AMT_TWD ELSE 0 END)FP_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND CURRENCY_CODE = 'TWD' THEN NET_COST_AMT_TWD ELSE 0 END)TWD_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND CURRENCY_CODE = 'USD' THEN NET_COST_AMT_TWD ELSE 0 END)USD_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND CURRENCY_CODE NOT IN('USD','TWD') THEN NET_COST_AMT_TWD ELSE 0 END)OD_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '110' THEN NET_COST_AMT_TWD ELSE 0 END)ST_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN ('150','450') THEN NET_COST_AMT_TWD ELSE 0 END)BSBL_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '160' THEN NET_COST_AMT_TWD ELSE 0 END)LOAN_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '210' THEN NET_COST_AMT_TWD ELSE 0 END)FS_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN('120','220','420') THEN NET_COST_AMT_TWD ELSE 0 END)FD_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '230' THEN NET_COST_AMT_TWD ELSE 0 END)FB_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN('540','240') THEN NET_COST_AMT_TWD ELSE 0 END)SN_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE = '6L0' THEN NET_COST_AMT_TWD ELSE 0 END)INSURANCE_NET_COST_12M
      ,SUM(CASE WHEN SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND PROD_MTYPE_CODE IN ('3C0','3F0','3P0') OR PROD_TYPE_CODE = '300'  THEN NET_COST_AMT_TWD ELSE 0 END)FU_NET_COST_12M
FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
INNER JOIN(SELECT DISTINCT CUSTOMER_ID FROM DS_SEC.CF_CUSTID WHERE YYYYMM = :ym)B
ON C.PARTY_ID_MASK = B.CUSTOMER_ID
WHERE SNAP_YYYYMM IN (:ym,TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM'),TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM'))
GROUP BY PARTY_ID_MASK;

/************************************對外輸出************************************************/
INSERT INTO DS_SEC.CF_INVBNF
SELECT CUSTOMER_ID
      ,A.YYYYMM
      ,ROUND(AP_INVBNF_M,0) AP_INVBNF_M
      ,ROUND(BR_INVBNF_M,0) BR_INVBNF_M
      ,ROUND(FP_INVBNF_M,0) FP_INVBNF_M
      ,ROUND(TWD_INVBNF_M,0) TWD_INVBNF_M
      ,ROUND(USD_INVBNF_M,0) USD_INVBNF_M
      ,ROUND(OD_INVBNF_M,0) OD_INVBNF_M
      ,ROUND(ST_INVBNF_M,0) ST_INVBNF_M
      ,ROUND(BSBL_INVBNF_M,0) BSBL_INVBNF_M
      ,ROUND(FS_INVBNF_M,0) FS_INVBNF_M
      ,ROUND(FD_INVBNF_M,0) FD_INVBNF_M
      ,ROUND(FB_INVBNF_M,0) FB_INVBNF_M
      ,ROUND(SN_INVBNF_M,0) SN_INVBNF_M
      ,ROUND(FU_INVBNF_M,0) FU_INVBNF_M
      
      ,ROUND(CASE WHEN NVL(AP_INVBNF_M,0) = 0 AND NVL(AP_INVBNF_L,0) = 0 THEN NULL ELSE NVL(AP_INVBNF_M,0) -NVL(AP_INVBNF_L,0) END,0) AS AP_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_M,0) = 0 AND NVL(BR_INVBNF_L,0) = 0 THEN NULL ELSE NVL(BR_INVBNF_M,0) -NVL(BR_INVBNF_L,0) END,0) AS BR_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FP_INVBNF_M,0) = 0 AND NVL(FP_INVBNF_L,0) = 0 THEN NULL ELSE NVL(FP_INVBNF_M,0) -NVL(FP_INVBNF_L,0) END,0) AS FP_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(TWD_INVBNF_M,0) = 0 AND NVL(TWD_INVBNF_L,0) = 0 THEN NULL ELSE NVL(TWD_INVBNF_M,0) -NVL(TWD_INVBNF_L,0) END,0) AS TWD_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(USD_INVBNF_M,0) = 0 AND NVL(USD_INVBNF_L,0) = 0 THEN NULL ELSE NVL(USD_INVBNF_M,0) -NVL(USD_INVBNF_L,0) END,0) AS USD_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(OD_INVBNF_M,0) = 0 AND NVL(OD_INVBNF_L,0) = 0 THEN NULL ELSE NVL(OD_INVBNF_M,0) -NVL(OD_INVBNF_L,0) END,0) AS OD_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(ST_INVBNF_M,0) = 0 AND NVL(ST_INVBNF_L,0) = 0 THEN NULL ELSE NVL(ST_INVBNF_M,0) -NVL(ST_INVBNF_L,0) END,0) AS ST_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(BSBL_INVBNF_M,0) = 0 AND NVL(BSBL_INVBNF_L,0) = 0 THEN NULL ELSE NVL(BSBL_INVBNF_M,0) -NVL(BSBL_INVBNF_L,0) END,0) AS BSBL_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FS_INVBNF_M,0) = 0 AND NVL(FS_INVBNF_L,0) = 0 THEN NULL ELSE NVL(FS_INVBNF_M,0) -NVL(FS_INVBNF_L,0) END,0) AS FS_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FD_INVBNF_M,0) = 0 AND NVL(FD_INVBNF_L,0) = 0 THEN NULL ELSE NVL(FD_INVBNF_M,0) -NVL(FD_INVBNF_L,0) END,0) AS FD_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FB_INVBNF_M,0) = 0 AND NVL(FB_INVBNF_L,0) = 0 THEN NULL ELSE NVL(FB_INVBNF_M,0) -NVL(FB_INVBNF_L,0) END,0) AS FB_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(SN_INVBNF_M,0) = 0 AND NVL(SN_INVBNF_L,0) = 0 THEN NULL ELSE NVL(SN_INVBNF_M,0) -NVL(SN_INVBNF_L,0) END,0) AS SN_INVBNF_M_MDIFF
      ,ROUND(CASE WHEN NVL(FU_INVBNF_M,0) = 0 AND NVL(FU_INVBNF_L,0) = 0 THEN NULL ELSE NVL(FU_INVBNF_M,0) -NVL(FU_INVBNF_L,0) END,0) AS FU_INVBNF_M_MDIFF
      
      ,ROUND(CASE WHEN NVL(AP_INVBNF_L,0)!=0 THEN (NVL(AP_INVBNF_M,0)/NVL(AP_INVBNF_L,0))-1 ELSE NULL END,4) AS AP_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_L,0)!=0 THEN (NVL(BR_INVBNF_M,0)/NVL(BR_INVBNF_L,0))-1 ELSE NULL END,4) AS BR_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FP_INVBNF_L,0)!=0 THEN (NVL(FP_INVBNF_M,0)/NVL(FP_INVBNF_L,0))-1 ELSE NULL END,4) AS FP_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(TWD_INVBNF_L,0)!=0 THEN (NVL(TWD_INVBNF_M,0)/NVL(TWD_INVBNF_L,0))-1 ELSE NULL END,4) AS TWD_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(USD_INVBNF_L,0)!=0 THEN (NVL(USD_INVBNF_M,0)/NVL(USD_INVBNF_L,0))-1 ELSE NULL END,4) AS USD_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(OD_INVBNF_L,0)!=0 THEN (NVL(OD_INVBNF_M,0)/NVL(OD_INVBNF_L,0))-1 ELSE NULL END,4) AS OD_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(ST_INVBNF_L,0)!=0 THEN (NVL(ST_INVBNF_M,0)/NVL(ST_INVBNF_L,0))-1 ELSE NULL END,4) AS ST_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(BSBL_INVBNF_L,0)!=0 THEN (NVL(BSBL_INVBNF_M,0)/NVL(BSBL_INVBNF_L,0))-1 ELSE NULL END,4) AS BSBL_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FS_INVBNF_L,0)!=0 THEN (NVL(FS_INVBNF_M,0)/NVL(FS_INVBNF_L,0))-1 ELSE NULL END,4) AS FS_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FD_INVBNF_L,0)!=0 THEN (NVL(FD_INVBNF_M,0)/NVL(FD_INVBNF_L,0))-1 ELSE NULL END,4) AS FD_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FB_INVBNF_L,0)!=0 THEN (NVL(FB_INVBNF_M,0)/NVL(FB_INVBNF_L,0))-1 ELSE NULL END,4) AS FB_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(SN_INVBNF_L,0)!=0 THEN (NVL(SN_INVBNF_M,0)/NVL(SN_INVBNF_L,0))-1 ELSE NULL END,4) AS SN_INVBNF_M_RDIFF
      ,ROUND(CASE WHEN NVL(FU_INVBNF_L,0)!=0 THEN (NVL(FU_INVBNF_M,0)/NVL(FU_INVBNF_L,0))-1 ELSE NULL END,4) AS FU_INVBNF_M_RDIFF
            
      ,ROUND(CASE WHEN NVL(AP_INVBNF_M,0) = 0 AND NVL(AP_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(AP_INVBNF_M,0) -NVL(AP_INVBNF_3M,0) END,0) AS AP_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_M,0) = 0 AND NVL(BR_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(BR_INVBNF_M,0) -NVL(BR_INVBNF_3M,0) END,0) AS BR_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FP_INVBNF_M,0) = 0 AND NVL(FP_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(FP_INVBNF_M,0) -NVL(FP_INVBNF_3M,0) END,0) AS FP_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(TWD_INVBNF_M,0) = 0 AND NVL(TWD_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(TWD_INVBNF_M,0) -NVL(TWD_INVBNF_3M,0) END,0) AS TWD_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(USD_INVBNF_M,0) = 0 AND NVL(USD_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(USD_INVBNF_M,0) -NVL(USD_INVBNF_3M,0) END,0) AS USD_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(OD_INVBNF_M,0) = 0 AND NVL(OD_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(OD_INVBNF_M,0) -NVL(OD_INVBNF_3M,0) END,0) AS OD_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(ST_INVBNF_M,0) = 0 AND NVL(ST_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(ST_INVBNF_M,0) -NVL(ST_INVBNF_3M,0) END,0) AS ST_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(BSBL_INVBNF_M,0) = 0 AND NVL(BSBL_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(BSBL_INVBNF_M,0) -NVL(BSBL_INVBNF_3M,0) END,0) AS BSBL_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FS_INVBNF_M,0) = 0 AND NVL(FS_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(FS_INVBNF_M,0) -NVL(FS_INVBNF_3M,0) END,0) AS FS_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FD_INVBNF_M,0) = 0 AND NVL(FD_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(FD_INVBNF_M,0) -NVL(FD_INVBNF_3M,0) END,0) AS FD_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FB_INVBNF_M,0) = 0 AND NVL(FB_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(FB_INVBNF_M,0) -NVL(FB_INVBNF_3M,0) END,0) AS FB_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(SN_INVBNF_M,0) = 0 AND NVL(SN_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(SN_INVBNF_M,0) -NVL(SN_INVBNF_3M,0) END,0) AS SN_INVBNF_3M_MDIFF
      ,ROUND(CASE WHEN NVL(FU_INVBNF_M,0) = 0 AND NVL(FU_INVBNF_3M,0) = 0 THEN NULL ELSE NVL(FU_INVBNF_M,0) -NVL(FU_INVBNF_3M,0) END,0) AS FU_INVBNF_3M_MDIFF

      ,ROUND(CASE WHEN NVL(AP_INVBNF_3M,0)!=0 THEN (NVL(AP_INVBNF_M,0)/NVL(AP_INVBNF_3M,0))-1 ELSE NULL END,4) AS AP_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_3M,0)!=0 THEN (NVL(BR_INVBNF_M,0)/NVL(BR_INVBNF_3M,0))-1 ELSE NULL END,4) AS BR_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FP_INVBNF_3M,0)!=0 THEN (NVL(FP_INVBNF_M,0)/NVL(FP_INVBNF_3M,0))-1 ELSE NULL END,4) AS FP_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(TWD_INVBNF_3M,0)!=0 THEN (NVL(TWD_INVBNF_M,0)/NVL(TWD_INVBNF_3M,0))-1 ELSE NULL END,4) AS TWD_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(USD_INVBNF_3M,0)!=0 THEN (NVL(USD_INVBNF_M,0)/NVL(USD_INVBNF_3M,0))-1 ELSE NULL END,4) AS USD_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(OD_INVBNF_3M,0)!=0 THEN (NVL(OD_INVBNF_M,0)/NVL(OD_INVBNF_3M,0))-1 ELSE NULL END,4) AS OD_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(ST_INVBNF_3M,0)!=0 THEN (NVL(ST_INVBNF_M,0)/NVL(ST_INVBNF_3M,0))-1 ELSE NULL END,4) AS ST_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(BSBL_INVBNF_3M,0)!=0 THEN (NVL(BSBL_INVBNF_M,0)/NVL(BSBL_INVBNF_3M,0))-1 ELSE NULL END,4) AS BSBL_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FS_INVBNF_3M,0)!=0 THEN (NVL(FS_INVBNF_M,0)/NVL(FS_INVBNF_3M,0))-1 ELSE NULL END,4) AS FS_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FD_INVBNF_3M,0)!=0 THEN (NVL(FD_INVBNF_M,0)/NVL(FD_INVBNF_3M,0))-1 ELSE NULL END,4) AS FD_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FB_INVBNF_3M,0)!=0 THEN (NVL(FB_INVBNF_M,0)/NVL(FB_INVBNF_3M,0))-1 ELSE NULL END,4) AS FB_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(SN_INVBNF_3M,0)!=0 THEN (NVL(SN_INVBNF_M,0)/NVL(SN_INVBNF_3M,0))-1 ELSE NULL END,4) AS SN_INVBNF_3M_RDIFF
      ,ROUND(CASE WHEN NVL(FU_INVBNF_3M,0)!=0 THEN (NVL(FU_INVBNF_M,0)/NVL(FU_INVBNF_3M,0))-1 ELSE NULL END,4) AS FU_INVBNF_3M_RDIFF
      
      ,ROUND(CASE WHEN NVL(AP_INVBNF_M,0) = 0 AND NVL(AP_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(AP_INVBNF_M,0) -NVL(AP_INVBNF_6M,0) END,0) AS AP_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_M,0) = 0 AND NVL(BR_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(BR_INVBNF_M,0) -NVL(BR_INVBNF_6M,0) END,0) AS BR_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(FP_INVBNF_M,0) = 0 AND NVL(FP_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(FP_INVBNF_M,0) -NVL(FP_INVBNF_6M,0) END,0) AS FP_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(TWD_INVBNF_M,0) = 0 AND NVL(TWD_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(TWD_INVBNF_M,0) -NVL(TWD_INVBNF_6M,0) END,0) AS TWD_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(USD_INVBNF_M,0) = 0 AND NVL(USD_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(USD_INVBNF_M,0) -NVL(USD_INVBNF_6M,0) END,0) AS USD_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(OD_INVBNF_M,0) = 0 AND NVL(OD_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(OD_INVBNF_M,0) -NVL(OD_INVBNF_6M,0) END,0) AS OD_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(ST_INVBNF_M,0) = 0 AND NVL(ST_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(ST_INVBNF_M,0) -NVL(ST_INVBNF_6M,0) END,0) AS ST_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(BSBL_INVBNF_M,0) = 0 AND NVL(BSBL_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(BSBL_INVBNF_M,0) -NVL(BSBL_INVBNF_6M,0) END,0) AS BSBL_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(FS_INVBNF_M,0) = 0 AND NVL(FS_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(FS_INVBNF_M,0) -NVL(FS_INVBNF_6M,0) END,0) AS FS_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(FD_INVBNF_M,0) = 0 AND NVL(FD_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(FD_INVBNF_M,0) -NVL(FD_INVBNF_6M,0) END,0) AS FD_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(FB_INVBNF_M,0) = 0 AND NVL(FB_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(FB_INVBNF_M,0) -NVL(FB_INVBNF_6M,0) END,0) AS FB_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(SN_INVBNF_M,0) = 0 AND NVL(SN_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(SN_INVBNF_M,0) -NVL(SN_INVBNF_6M,0) END,0) AS SN_INVBNF_6M_MDIFF
      ,ROUND(CASE WHEN NVL(FU_INVBNF_M,0) = 0 AND NVL(FU_INVBNF_6M,0) = 0 THEN NULL ELSE NVL(FU_INVBNF_M,0) -NVL(FU_INVBNF_6M,0) END,0) AS FU_INVBNF_6M_MDIFF
      
      ,ROUND(CASE WHEN NVL(AP_INVBNF_6M,0)!=0 THEN (NVL(AP_INVBNF_M,0)/NVL(AP_INVBNF_6M,0))-1 ELSE NULL END,4) AS AP_INVBNF_6M_RDIFF
      ,ROUND(CASE WHEN NVL(BR_INVBNF_6M,0)!=0 THEN (NVL(BR_INVBNF_M,0)/NVL(BR_INVBNF_6M,0))-1 ELSE NULL END,4) AS BR_INVBNF_6M_RDIFF
