      ,ROUND(CASE WHEN NVL(BR_INVBNF_12M,0)!=0 THEN (NVL(BR_INVBNF_M,0)/NVL(BR_INVBNF_12M,0))-1 ELSE NULL END,4) AS BR_INVBNF_12M_RDIFF
