      ,CASE WHEN NVL(USD_NET_COST_12M,0)!=0 THEN (NVL(USD_INVBNF_12M,0)/NVL(USD_NET_COST_12M,0)) ELSE NULL END AS USD_ROI_12M
      ,CASE WHEN NVL(OD_NET_COST_12M,0)!=0 THEN (NVL(OD_INVBNF_12M,0)/NVL(OD_NET_COST_12M,0)) ELSE NULL END AS OD_ROI_12M
      ,CASE WHEN NVL(ST_NET_COST_12M,0)!=0 THEN (NVL(ST_INVBNF_12M,0)/NVL(ST_NET_COST_12M,0)) ELSE NULL END AS ST_ROI_12M
      ,CASE WHEN NVL(BSBL_NET_COST_12M,0)!=0 THEN (NVL(BSBL_INVBNF_12M,0)/NVL(BSBL_NET_COST_12M,0)) ELSE NULL END AS BSBL_ROI_12M
      ,CASE WHEN NVL(LOAN_NET_COST_12M,0)!=0 THEN (NVL(LOAN_INVBNF_12M,0)/NVL(LOAN_NET_COST_12M,0)) ELSE NULL END AS LOAN_ROI_12M
      ,CASE WHEN NVL(FS_NET_COST_12M,0)!=0 THEN (NVL(FS_INVBNF_12M,0)/NVL(FS_NET_COST_12M,0)) ELSE NULL END AS FS_ROI_12M
      ,CASE WHEN NVL(FD_NET_COST_12M,0)!=0 THEN (NVL(FD_INVBNF_12M,0)/NVL(FD_NET_COST_12M,0)) ELSE NULL END AS FD_ROI_12M
      ,CASE WHEN NVL(FB_NET_COST_12M,0)!=0 THEN (NVL(FB_INVBNF_12M,0)/NVL(FB_NET_COST_12M,0)) ELSE NULL END AS FB_ROI_12M
      ,CASE WHEN NVL(SN_NET_COST_12M,0)!=0 THEN (NVL(SN_INVBNF_12M,0)/NVL(SN_NET_COST_12M,0)) ELSE NULL END AS SN_ROI_12M
      ,CASE WHEN NVL(INSURANCE_NET_COST_12M,0)!=0 THEN (NVL(INSURANCE_INVBNF_12M,0)/NVL(INSURANCE_NET_COST_12M,0)) ELSE NULL END AS INSURANCE_ROI_12M
      ,CASE WHEN NVL(FU_NET_COST_12M,0)!=0 THEN (NVL(FU_INVBNF_12M,0)/NVL(FU_NET_COST_12M,0)) ELSE NULL END AS FU_ROI_12M
FROM TEMP5INVBNF)B
ON A.CUSTOMER_ID  = B.PARTY_ID
WHERE A.YYYYMM = :ym
;
DROP TABLE TEMP5INVBNF PURGE;

/************************************內部建置************************************************/
CREATE TABLE TEMP6ASSET1
AS
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      -- 經紀商品
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('110', '150', '160', '210') THEN A.BAL_AMT_TWD  
                WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('3CP','3FS') THEN A.EQUITY_AMT_TWD ELSE 0 END) BR_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('110', '150', '160', '210') THEN A.BAL_AMT_TWD  
                WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('3CP','3FS') THEN A.EQUITY_AMT_TWD  ELSE 0 END) BR_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('110', '150', '160', '210') THEN A.BAL_AMT_TWD  
                WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('3CP','3FS') THEN A.EQUITY_AMT_TWD  ELSE 0 END) BR_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('110', '150', '160', '210') THEN A.BAL_AMT_TWD  
                WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('3CP','3FS') THEN A.EQUITY_AMT_TWD  ELSE 0 END) BR_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('110', '150', '160', '210') THEN A.BAL_AMT_TWD  
                WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('3CP','3FS') THEN A.EQUITY_AMT_TWD  ELSE 0 END) BR_SAFE_STOCK_L
      
      -- 財管商品 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.BAL_AMT_TWD ELSE 0 END) FP_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.BAL_AMT_TWD ELSE 0 END) FP_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.BAL_AMT_TWD ELSE 0 END) FP_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.BAL_AMT_TWD ELSE 0 END) FP_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.BAL_AMT_TWD ELSE 0 END) FP_SAFE_STOCK_L
      
      -- 台幣計價
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN 1 ELSE 0 END) TWD_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN 1 ELSE 0 END) TWD_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN 1 ELSE 0 END) TWD_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='TWD' THEN A.BAL_AMT_TWD ELSE 0 END) TWD_AS_ASSET_12M
     
      -- 美元計價
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN 1 ELSE 0 END) USD_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN 1 ELSE 0 END) USD_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN 1 ELSE 0 END) USD_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE='USD' THEN A.BAL_AMT_TWD ELSE 0 END) USD_AS_ASSET_12M
      
      -- 其他幣別計價
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN 1 ELSE 0 END) OD_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN 1 ELSE 0 END) OD_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN 1 ELSE 0 END) OD_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.CURRENCY_CODE NOT IN ('USD', 'TWD') THEN A.BAL_AMT_TWD ELSE 0 END) OD_AS_ASSET_12M
      
      -- 一般股票
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN 1 ELSE 0 END) STGS_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN 1 ELSE 0 END) STGS_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN 1 ELSE 0 END) STGS_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='011' THEN A.BAL_AMT_TWD ELSE 0 END) STGS_AS_ASSET_12M

      -- 認股權證
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN 1 ELSE 0 END) STWA_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN 1 ELSE 0 END) STWA_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN 1 ELSE 0 END) STWA_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='012' THEN A.BAL_AMT_TWD ELSE 0 END) STWA_AS_ASSET_12M
      
      -- 股票ETF
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_SAFE_STOCK_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN 1 ELSE 0 END) STETF_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN 1 ELSE 0 END) STETF_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN 1 ELSE 0 END) STETF_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='019' THEN A.BAL_AMT_TWD ELSE 0 END) STETF_AS_ASSET_12M
      
      -- 其他類股票
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_STYPE_CODE IN ('013', '014', '015', '016', '017', '018') THEN A.BAL_AMT_TWD ELSE 0 END) OST_SAFE_STOCK_M
