      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN 1 ELSE 0 END) FDST_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN 1 ELSE 0 END) FDST_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN 1 ELSE 0 END) FDST_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE='021' THEN A.BAL_AMT_TWD ELSE 0 END) FDST_AS_ASSET_12M
      
      -- 其他型基金
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_SAFE_STOCK_L
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN 1 ELSE 0 END) OFD_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN 1 ELSE 0 END) OFD_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN 1 ELSE 0 END) OFD_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_STYPE_CODE IN ('025', '026') THEN A.BAL_AMT_TWD ELSE 0 END) OFD_AS_ASSET_12M
  
     -- 內期
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='3CP' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFC_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE='3CP' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFC_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE='3CP' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFC_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE='3CP' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFC_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE='3CP' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFC_SAFE_STOCK_L
      
      -- 外期
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='3FS' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFF_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE='3FS' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFF_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE='3FS' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFF_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE='3FS' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFF_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE='3FS' THEN A.EQUITY_AMT_TWD ELSE 0 END) UFF_SAFE_STOCK_L

      -- 境內結構型
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='540' THEN A.BAL_AMT_TWD ELSE 0 END) NSN_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE='540' THEN A.BAL_AMT_TWD ELSE 0 END) NSN_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE='540' THEN A.BAL_AMT_TWD ELSE 0 END) NSN_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE='540' THEN A.BAL_AMT_TWD ELSE 0 END) NSN_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE='540' THEN A.BAL_AMT_TWD ELSE 0 END) NSN_SAFE_STOCK_L

     -- 境外結構型 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='240' THEN A.BAL_AMT_TWD ELSE 0 END) FSN_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE='240' THEN A.BAL_AMT_TWD ELSE 0 END) FSN_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE='240' THEN A.BAL_AMT_TWD ELSE 0 END) FSN_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE='240' THEN A.BAL_AMT_TWD ELSE 0 END) FSN_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE='240' THEN A.BAL_AMT_TWD ELSE 0 END) FSN_SAFE_STOCK_L

     -- 選擇權
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='3P0' THEN A.BAL_AMT_TWD ELSE 0 END) OP_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -3), 'YYYYMM') AND A.PROD_MTYPE_CODE='3P0' THEN A.BAL_AMT_TWD ELSE 0 END) OP_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -6), 'YYYYMM') AND A.PROD_MTYPE_CODE='3P0' THEN A.BAL_AMT_TWD ELSE 0 END) OP_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND A.PROD_MTYPE_CODE='3P0' THEN A.BAL_AMT_TWD ELSE 0 END) OP_SAFE_STOCK_12M 
      ,SUM(CASE WHEN A.SNAP_YYYYMM = TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -1), 'YYYYMM') AND A.PROD_MTYPE_CODE='3P0' THEN A.BAL_AMT_TWD ELSE 0 END) OP_SAFE_STOCK_L
   
FROM DM_S_VIEW.M_AC_ACCOUNT_INVENTORY A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
INNER JOIN (SELECT DISTINCT CUSTOMER_ID FROM DS_SEC.CF_CUSTID WHERE YYYYMM = :ym) B
ON C.PARTY_ID_MASK = B.CUSTOMER_ID 
WHERE SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -12), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK;

CREATE TABLE TEMP6ASSET2
AS
SELECT PARTY_ID_MASK AS CUSTOMER_ID
      -- 所有商品
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym THEN 1 ELSE 0 END) AP_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN 1 ELSE 0 END) AP_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN 1 ELSE 0 END) AP_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN 1 ELSE 0 END) AP_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) AP_AS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) AP_AS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) AP_AS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) AP_AS_SAFE_STOCK_12M
      
      -- 經紀商品
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN 1 ELSE 0 END) BR_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN 1 ELSE 0 END) BR_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN 1 ELSE 0 END) BR_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN 1 ELSE 0 END) BR_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) BR_AS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) BR_AS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) BR_AS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('110', '210', '150', '160', '3C0','3F0','3P0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) BR_AS_SAFE_STOCK_12M

      -- 財管商品
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN 1 ELSE 0 END) FP_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN 1 ELSE 0 END) FP_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN 1 ELSE 0 END) FP_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN 1 ELSE 0 END) FP_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FP_AS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FP_AS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FP_AS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE IN ('120', '220', '230', '420', '240', '540', '6L0') THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FP_AS_SAFE_STOCK_12M
        
      -- 台股現貨
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN 1 ELSE 0 END) STST_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN 1 ELSE 0 END) STST_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN 1 ELSE 0 END) STST_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN 1 ELSE 0 END) STST_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STST_AS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STST_AS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='111A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STST_AS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110'AND A.ASSET_CODE='111A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STST_AS_SAFE_STOCK_12M

      -- 台股融資
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN 1 ELSE 0 END) STMT_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN 1 ELSE 0 END) STMT_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN 1 ELSE 0 END) STMT_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN 1 ELSE 0 END) STMT_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STMT_AS_SAFE_STOCK_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STMT_AS_SAFE_STOCK_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110' AND A.ASSET_CODE='112A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STMT_AS_SAFE_STOCK_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='110'AND A.ASSET_CODE='112A01' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) STMT_AS_SAFE_STOCK_12M
      
