      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='240' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FSN_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='240' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) FSN_AS_ASSET_12M
     
     -- 選擇權
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='3P0' THEN 1 ELSE 0 END) OP_COUNT_NUM_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN 1 ELSE 0 END) OP_COUNT_NUM_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN 1 ELSE 0 END) OP_COUNT_NUM_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN 1 ELSE 0 END) OP_COUNT_NUM_12M
      ,SUM(CASE WHEN A.SNAP_YYYYMM = :ym AND A.PROD_MTYPE_CODE='3P0' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) OP_AS_ASSET_M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -2), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) OP_AS_ASSET_3M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -5), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) OP_AS_ASSET_6M
      ,SUM(CASE WHEN A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym AND A.PROD_MTYPE_CODE='3P0' THEN A.AVG_ASSET_AMT_TWD ELSE 0 END) OP_AS_ASSET_12M
      
FROM DM_S_VIEW.M_AC_ACCOUNT_ASSET A
LEFT JOIN (SELECT DISTINCT PARTY_ID,PARTY_ID_MASK FROM DM_S_VIEW.M_AC_ACCOUNT) C
ON A.PARTY_ID = C.PARTY_ID
INNER JOIN (SELECT DISTINCT CUSTOMER_ID FROM DS_SEC.CF_CUSTID WHERE YYYYMM = :ym) B
ON C.PARTY_ID_MASK = B.CUSTOMER_ID 
WHERE A.SNAP_YYYYMM BETWEEN TO_CHAR(ADD_MONTHS(TO_DATE(:ym || '01', 'YYYYMMDD'), -11), 'YYYYMM') AND :ym
GROUP BY PARTY_ID_MASK;

/************************************對外輸出************************************************/

INSERT INTO DS_SEC.CF_ASSET1
SELECT A.CUSTOMER_ID
    ,A.YYYYMM
    -- 所有商品
    ,ROUND(CASE WHEN C.AP_COUNT_NUM_M != 0 THEN C.AP_AS_SAFE_STOCK_M / C.AP_COUNT_NUM_M ELSE 0 END,0) AS AP_AVGASSET_M
    ,ROUND(CASE WHEN C.AP_COUNT_NUM_3M != 0 THEN C.AP_AS_SAFE_STOCK_3M / C.AP_COUNT_NUM_3M ELSE 0 END,0) AS AP_AVGASSET_3M
    ,ROUND(CASE WHEN C.AP_COUNT_NUM_6M != 0 THEN C.AP_AS_SAFE_STOCK_6M / C.AP_COUNT_NUM_6M ELSE 0 END,0) AS AP_AVGASSET_6M
    ,ROUND(CASE WHEN C.AP_COUNT_NUM_12M != 0 THEN C.AP_AS_SAFE_STOCK_12M / C.AP_COUNT_NUM_12M ELSE 0 END,0) AS AP_AVGASSET_12M
    
    -- 經紀商品
    ,ROUND(CASE WHEN C.BR_COUNT_NUM_M != 0 THEN C.BR_AS_SAFE_STOCK_M / C.BR_COUNT_NUM_M ELSE 0 END,0) AS BR_AVGASSET_M
    ,ROUND(CASE WHEN C.BR_COUNT_NUM_3M != 0 THEN C.BR_AS_SAFE_STOCK_3M / C.BR_COUNT_NUM_3M ELSE 0 END,0) AS BR_AVGASSET_3M
    ,ROUND(CASE WHEN C.BR_COUNT_NUM_6M != 0 THEN C.BR_AS_SAFE_STOCK_6M / C.BR_COUNT_NUM_6M ELSE 0 END,0) AS BR_AVGASSET_6M
    ,ROUND(CASE WHEN C.BR_COUNT_NUM_12M != 0 THEN C.BR_AS_SAFE_STOCK_12M / C.BR_COUNT_NUM_12M ELSE 0 END,0) AS BR_AVGASSET_12M
    ,ROUND(B.BR_SAFE_STOCK_M,0) AS BR_ASSET_M
    ,ROUND(B.BR_SAFE_STOCK_M - B.BR_SAFE_STOCK_L,0) AS BR_ASSET_M_MDIFF
    ,ROUND(B.BR_SAFE_STOCK_M - B.BR_SAFE_STOCK_3M,0) AS BR_ASSET_3M_MDIFF
    ,ROUND(B.BR_SAFE_STOCK_M - B.BR_SAFE_STOCK_6M,0) AS BR_ASSET_6M_MDIFF
    ,ROUND(B.BR_SAFE_STOCK_M - B.BR_SAFE_STOCK_12M,0) AS BR_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.BR_SAFE_STOCK_L != 0 THEN (B.BR_SAFE_STOCK_M / B.BR_SAFE_STOCK_L)-1 ELSE 0 END,4) AS BR_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.BR_SAFE_STOCK_3M != 0 THEN (B.BR_SAFE_STOCK_M / B.BR_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS BR_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.BR_SAFE_STOCK_6M != 0 THEN (B.BR_SAFE_STOCK_M / B.BR_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS BR_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.BR_SAFE_STOCK_12M != 0 THEN (B.BR_SAFE_STOCK_M / B.BR_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS BR_ASSET_12M_RDIFF
    
    -- 財管商品
    ,ROUND(CASE WHEN C.FP_COUNT_NUM_M != 0 THEN C.FP_AS_SAFE_STOCK_M / C.FP_COUNT_NUM_M ELSE 0 END,0) AS FP_AVGASSET_M
    ,ROUND(CASE WHEN C.FP_COUNT_NUM_3M != 0 THEN C.FP_AS_SAFE_STOCK_3M / C.FP_COUNT_NUM_3M ELSE 0 END,0) AS FP_AVGASSET_3M
    ,ROUND(CASE WHEN C.FP_COUNT_NUM_6M != 0 THEN C.FP_AS_SAFE_STOCK_6M / C.FP_COUNT_NUM_6M ELSE 0 END,0) AS FP_AVGASSET_6M
    ,ROUND(CASE WHEN C.FP_COUNT_NUM_12M != 0 THEN C.FP_AS_SAFE_STOCK_12M / C.FP_COUNT_NUM_12M ELSE 0 END,0) AS FP_AVGASSET_12M
    ,ROUND(B.FP_SAFE_STOCK_M,0) AS FP_ASSET_M
    ,ROUND(B.FP_SAFE_STOCK_M - B.FP_SAFE_STOCK_L,0) AS FP_ASSET_M_MDIFF
    ,ROUND(B.FP_SAFE_STOCK_M - B.FP_SAFE_STOCK_3M,0) AS FP_ASSET_3M_MDIFF
    ,ROUND(B.FP_SAFE_STOCK_M - B.FP_SAFE_STOCK_6M,0) AS FP_ASSET_6M_MDIFF
    ,ROUND(B.FP_SAFE_STOCK_M - B.FP_SAFE_STOCK_12M,0) AS FP_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FP_SAFE_STOCK_L != 0 THEN (B.FP_SAFE_STOCK_M / B.FP_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FP_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FP_SAFE_STOCK_3M != 0 THEN (B.FP_SAFE_STOCK_M / B.FP_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FP_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FP_SAFE_STOCK_6M != 0 THEN (B.FP_SAFE_STOCK_M / B.FP_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FP_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FP_SAFE_STOCK_12M != 0 THEN (B.FP_SAFE_STOCK_M / B.FP_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FP_ASSET_12M_RDIFF
    
    -- 台幣計價
    ,ROUND(B.TWD_SAFE_STOCK_M,0) AS TWD_AVGASSET_M
    ,ROUND(CASE WHEN B.TWD_COUNT_NUM_3M != 0 THEN B.TWD_AS_ASSET_3M / B.TWD_COUNT_NUM_3M ELSE 0 END,0) AS TWD_AVGASSET_3M
    ,ROUND(CASE WHEN B.TWD_COUNT_NUM_6M != 0 THEN B.TWD_AS_ASSET_6M / B.TWD_COUNT_NUM_6M ELSE 0 END,0) AS TWD_AVGASSET_6M
    ,ROUND(CASE WHEN B.TWD_COUNT_NUM_12M != 0 THEN B.TWD_AS_ASSET_12M / B.TWD_COUNT_NUM_12M ELSE 0 END,0) AS TWD_AVGASSET_12M
    ,ROUND(B.TWD_SAFE_STOCK_M,0) AS TWD_ASSET_M
    ,ROUND(B.TWD_SAFE_STOCK_M - B.TWD_SAFE_STOCK_L,0) AS TWD_ASSET_M_MDIFF
    ,ROUND(B.TWD_SAFE_STOCK_M - B.TWD_SAFE_STOCK_3M,0) AS TWD_ASSET_3M_MDIFF
    ,ROUND(B.TWD_SAFE_STOCK_M - B.TWD_SAFE_STOCK_6M,0) AS TWD_ASSET_6M_MDIFF
    ,ROUND(B.TWD_SAFE_STOCK_M - B.TWD_SAFE_STOCK_12M,0) AS TWD_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.TWD_SAFE_STOCK_L != 0 THEN (B.TWD_SAFE_STOCK_M / B.TWD_SAFE_STOCK_L)-1 ELSE 0 END,4) AS TWD_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.TWD_SAFE_STOCK_3M != 0 THEN (B.TWD_SAFE_STOCK_M / B.TWD_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS TWD_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.TWD_SAFE_STOCK_6M != 0 THEN (B.TWD_SAFE_STOCK_M / B.TWD_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS TWD_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.TWD_SAFE_STOCK_12M != 0 THEN (B.TWD_SAFE_STOCK_M / B.TWD_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS TWD_ASSET_12M_RDIFF
    
    -- 美元計價
    ,ROUND(B.USD_SAFE_STOCK_M,0) AS USD_AVGASSET_M
    ,ROUND(CASE WHEN B.USD_COUNT_NUM_3M != 0 THEN B.USD_AS_ASSET_3M / B.USD_COUNT_NUM_3M ELSE 0 END,0) AS USD_AVGASSET_3M
    ,ROUND(CASE WHEN B.USD_COUNT_NUM_6M != 0 THEN B.USD_AS_ASSET_6M / B.USD_COUNT_NUM_6M ELSE 0 END,0) AS USD_AVGASSET_6M
    ,ROUND(CASE WHEN B.USD_COUNT_NUM_12M != 0 THEN B.USD_AS_ASSET_12M / B.USD_COUNT_NUM_12M ELSE 0 END,0) AS USD_AVGASSET_12M
    ,ROUND(B.USD_SAFE_STOCK_M,0) AS USD_ASSET_M
    ,ROUND(B.USD_SAFE_STOCK_M - B.USD_SAFE_STOCK_L,0) AS USD_ASSET_M_MDIFF
    ,ROUND(B.USD_SAFE_STOCK_M - B.USD_SAFE_STOCK_3M,0) AS USD_ASSET_3M_MDIFF
    ,ROUND(B.USD_SAFE_STOCK_M - B.USD_SAFE_STOCK_6M,0) AS USD_ASSET_6M_MDIFF
    ,ROUND(B.USD_SAFE_STOCK_M - B.USD_SAFE_STOCK_12M,0) AS USD_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.USD_SAFE_STOCK_L != 0 THEN (B.USD_SAFE_STOCK_M / B.USD_SAFE_STOCK_L)-1 ELSE 0 END,4) AS USD_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.USD_SAFE_STOCK_3M != 0 THEN (B.USD_SAFE_STOCK_M / B.USD_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS USD_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.USD_SAFE_STOCK_6M != 0 THEN (B.USD_SAFE_STOCK_M / B.USD_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS USD_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.USD_SAFE_STOCK_12M != 0 THEN (B.USD_SAFE_STOCK_M / B.USD_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS USD_ASSET_12M_RDIFF
    
    -- 其他幣別計價
    ,ROUND(B.OD_SAFE_STOCK_M,0) AS OD_AVGASSET_M
    ,ROUND(CASE WHEN B.OD_COUNT_NUM_3M != 0 THEN B.OD_AS_ASSET_3M / B.OD_COUNT_NUM_3M ELSE 0 END,0) AS OD_AVGASSET_3M
    ,ROUND(CASE WHEN B.OD_COUNT_NUM_6M != 0 THEN B.OD_AS_ASSET_6M / B.OD_COUNT_NUM_6M ELSE 0 END,0) AS OD_AVGASSET_6M
    ,ROUND(CASE WHEN B.OD_COUNT_NUM_12M != 0 THEN B.OD_AS_ASSET_12M / B.OD_COUNT_NUM_12M ELSE 0 END,0) AS OD_AVGASSET_12M
    ,ROUND(B.OD_SAFE_STOCK_M,0) AS OD_ASSET_M
    ,ROUND(B.OD_SAFE_STOCK_M - B.OD_SAFE_STOCK_L,0) AS OD_ASSET_M_MDIFF
    ,ROUND(B.OD_SAFE_STOCK_M - B.OD_SAFE_STOCK_3M,0) AS OD_ASSET_3M_MDIFF
    ,ROUND(B.OD_SAFE_STOCK_M - B.OD_SAFE_STOCK_6M,0) AS OD_ASSET_6M_MDIFF
    ,ROUND(B.OD_SAFE_STOCK_M - B.OD_SAFE_STOCK_12M,0) AS OD_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.OD_SAFE_STOCK_L != 0 THEN (B.OD_SAFE_STOCK_M / B.OD_SAFE_STOCK_L)-1 ELSE 0 END,4) AS OD_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.OD_SAFE_STOCK_3M != 0 THEN (B.OD_SAFE_STOCK_M / B.OD_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS OD_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.OD_SAFE_STOCK_6M != 0 THEN (B.OD_SAFE_STOCK_M / B.OD_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS OD_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.OD_SAFE_STOCK_12M != 0 THEN (B.OD_SAFE_STOCK_M / B.OD_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS OD_ASSET_12M_RDIFF
    
    -- 台股現貨
    ,ROUND(CASE WHEN C.STST_COUNT_NUM_M != 0 THEN C.STST_AS_SAFE_STOCK_M / C.STST_COUNT_NUM_M ELSE 0 END,0) AS STST_AVGASSET_M
    ,ROUND(CASE WHEN C.STST_COUNT_NUM_3M != 0 THEN C.STST_AS_SAFE_STOCK_3M / C.STST_COUNT_NUM_3M ELSE 0 END,0) AS STST_AVGASSET_3M
    ,ROUND(CASE WHEN C.STST_COUNT_NUM_6M != 0 THEN C.STST_AS_SAFE_STOCK_6M / C.STST_COUNT_NUM_6M ELSE 0 END,0) AS STST_AVGASSET_6M
    ,ROUND(CASE WHEN C.STST_COUNT_NUM_12M != 0 THEN C.STST_AS_SAFE_STOCK_12M / C.STST_COUNT_NUM_12M ELSE 0 END,0) AS STST_AVGASSET_12M
    
    -- 台股融資
    ,ROUND(CASE WHEN C.STMT_COUNT_NUM_M != 0 THEN C.STMT_AS_SAFE_STOCK_M / C.STMT_COUNT_NUM_M ELSE 0 END,0) AS STMT_AVGASSET_M
    ,ROUND(CASE WHEN C.STMT_COUNT_NUM_3M != 0 THEN C.STMT_AS_SAFE_STOCK_3M / C.STMT_COUNT_NUM_3M ELSE 0 END,0) AS STMT_AVGASSET_3M
    ,ROUND(CASE WHEN C.STMT_COUNT_NUM_6M != 0 THEN C.STMT_AS_SAFE_STOCK_6M / C.STMT_COUNT_NUM_6M ELSE 0 END,0) AS STMT_AVGASSET_6M
    ,ROUND(CASE WHEN C.STMT_COUNT_NUM_12M != 0 THEN C.STMT_AS_SAFE_STOCK_12M / C.STMT_COUNT_NUM_12M ELSE 0 END,0) AS STMT_AVGASSET_12M
    
    -- 台股融券
    ,ROUND(CASE WHEN C.STSS_COUNT_NUM_M != 0 THEN C.STSS_AS_SAFE_STOCK_M / C.STSS_COUNT_NUM_M ELSE 0 END,0) AS STSS_AVGASSET_M
    ,ROUND(CASE WHEN C.STSS_COUNT_NUM_3M != 0 THEN C.STSS_AS_SAFE_STOCK_3M / C.STSS_COUNT_NUM_3M ELSE 0 END,0) AS STSS_AVGASSET_3M
    ,ROUND(CASE WHEN C.STSS_COUNT_NUM_6M != 0 THEN C.STSS_AS_SAFE_STOCK_6M / C.STSS_COUNT_NUM_6M ELSE 0 END,0) AS STSS_AVGASSET_6M
    ,ROUND(CASE WHEN C.STSS_COUNT_NUM_12M != 0 THEN C.STSS_AS_SAFE_STOCK_12M / C.STSS_COUNT_NUM_12M ELSE 0 END,0) AS STSS_AVGASSET_12M
    
    -- 雙向借券
    ,ROUND(CASE WHEN C.BSBL_COUNT_NUM_M != 0 THEN C.BSBL_AS_SAFE_STOCK_M / C.BSBL_COUNT_NUM_M ELSE 0 END,0) AS BSBL_AVGASSET_M
    ,ROUND(CASE WHEN C.BSBL_COUNT_NUM_3M != 0 THEN C.BSBL_AS_SAFE_STOCK_3M / C.BSBL_COUNT_NUM_3M ELSE 0 END,0) AS BSBL_AVGASSET_3M
    ,ROUND(CASE WHEN C.BSBL_COUNT_NUM_6M != 0 THEN C.BSBL_AS_SAFE_STOCK_6M / C.BSBL_COUNT_NUM_6M ELSE 0 END,0) AS BSBL_AVGASSET_6M
    ,ROUND(CASE WHEN C.BSBL_COUNT_NUM_12M != 0 THEN C.BSBL_AS_SAFE_STOCK_12M / C.BSBL_COUNT_NUM_12M ELSE 0 END,0) AS BSBL_AVGASSET_12M
    
    -- 海外股票
    ,ROUND(CASE WHEN C.FS_COUNT_NUM_M != 0 THEN C.FS_AS_SAFE_STOCK_M / C.FS_COUNT_NUM_M ELSE 0 END,0) AS FS_AVGASSET_M
    ,ROUND(CASE WHEN C.FS_COUNT_NUM_3M != 0 THEN C.FS_AS_SAFE_STOCK_3M / C.FS_COUNT_NUM_3M ELSE 0 END,0) AS FS_AVGASSET_3M
    ,ROUND(CASE WHEN C.FS_COUNT_NUM_6M != 0 THEN C.FS_AS_SAFE_STOCK_6M / C.FS_COUNT_NUM_6M ELSE 0 END,0) AS FS_AVGASSET_6M
    ,ROUND(CASE WHEN C.FS_COUNT_NUM_12M != 0 THEN C.FS_AS_SAFE_STOCK_12M / C.FS_COUNT_NUM_12M ELSE 0 END,0) AS FS_AVGASSET_12M
    
    -- 海外債
    ,ROUND(CASE WHEN C.FB_COUNT_NUM_M != 0 THEN C.FB_AS_SAFE_STOCK_M / C.FB_COUNT_NUM_M ELSE 0 END,0) AS FB_AVGASSET_M
    ,ROUND(CASE WHEN C.FB_COUNT_NUM_3M != 0 THEN C.FB_AS_SAFE_STOCK_3M / C.FB_COUNT_NUM_3M ELSE 0 END,0) AS FB_AVGASSET_3M
    ,ROUND(CASE WHEN C.FB_COUNT_NUM_6M != 0 THEN C.FB_AS_SAFE_STOCK_6M / C.FB_COUNT_NUM_6M ELSE 0 END,0) AS FB_AVGASSET_6M
    ,ROUND(CASE WHEN C.FB_COUNT_NUM_12M != 0 THEN C.FB_AS_SAFE_STOCK_12M / C.FB_COUNT_NUM_12M ELSE 0 END,0) AS FB_AVGASSET_12M
    
    -- 基金
    ,ROUND(CASE WHEN C.FD_COUNT_NUM_M != 0 THEN C.FD_AS_SAFE_STOCK_M / C. FD_COUNT_NUM_M ELSE 0 END,0) AS FD_AVGASSET_M
    ,ROUND(CASE WHEN C.FD_COUNT_NUM_3M != 0 THEN C.FD_AS_SAFE_STOCK_3M / C. FD_COUNT_NUM_3M ELSE 0 END,0) AS FD_AVGASSET_3M
    ,ROUND(CASE WHEN C.FD_COUNT_NUM_6M != 0 THEN C.FD_AS_SAFE_STOCK_6M / C. FD_COUNT_NUM_6M ELSE 0 END,0) AS FD_AVGASSET_6M
    ,ROUND(CASE WHEN C.FD_COUNT_NUM_12M != 0 THEN C.FD_AS_SAFE_STOCK_12M / C. FD_COUNT_NUM_12M ELSE 0 END,0) AS FD_AVGASSET_12M
    
    -- 結構型商品
    ,ROUND(CASE WHEN C.SN_COUNT_NUM_M != 0 THEN C.SN_AS_SAFE_STOCK_M / C.SN_COUNT_NUM_M ELSE 0 END,0) AS SN_AVGASSET_M
    ,ROUND(CASE WHEN C.SN_COUNT_NUM_3M != 0 THEN C.SN_AS_SAFE_STOCK_3M / C.SN_COUNT_NUM_3M ELSE 0 END,0) AS SN_AVGASSET_3M
    ,ROUND(CASE WHEN C.SN_COUNT_NUM_6M != 0 THEN C.SN_AS_SAFE_STOCK_6M / C.SN_COUNT_NUM_6M ELSE 0 END,0) AS SN_AVGASSET_6M
    ,ROUND(CASE WHEN C.SN_COUNT_NUM_12M != 0 THEN C.SN_AS_SAFE_STOCK_12M / C.SN_COUNT_NUM_12M ELSE 0 END,0) AS SN_AVGASSET_12M
    
    -- 不限用途
    ,ROUND(CASE WHEN C.LOAN_COUNT_NUM_M != 0 THEN C.LOAN_AS_SAFE_STOCK_M / C.LOAN_COUNT_NUM_M ELSE 0 END,0) AS LOAN_AVGASSET_M
    ,ROUND(CASE WHEN C.LOAN_COUNT_NUM_3M != 0 THEN C.LOAN_AS_SAFE_STOCK_3M / C.LOAN_COUNT_NUM_3M ELSE 0 END,0) AS LOAN_AVGASSET_3M
    ,ROUND(CASE WHEN C.LOAN_COUNT_NUM_6M != 0 THEN C.LOAN_AS_SAFE_STOCK_6M / C.LOAN_COUNT_NUM_6M ELSE 0 END,0) AS LOAN_AVGASSET_6M
    ,ROUND(CASE WHEN C.LOAN_COUNT_NUM_12M != 0 THEN C.LOAN_AS_SAFE_STOCK_12M / C.LOAN_COUNT_NUM_12M ELSE 0 END,0) AS LOAN_AVGASSET_12M
    
    -- 期權
    ,ROUND(CASE WHEN C.FO_COUNT_NUM_M != 0 THEN C.FO_AS_SAFE_STOCK_M / C.FO_COUNT_NUM_M ELSE 0 END,0) AS FO_AVGASSET_M
    ,ROUND(CASE WHEN C.FO_COUNT_NUM_3M != 0 THEN C.FO_AS_SAFE_STOCK_3M / C.FO_COUNT_NUM_3M ELSE 0 END,0) AS FO_AVGASSET_3M
    ,ROUND(CASE WHEN C.FO_COUNT_NUM_6M != 0 THEN C.FO_AS_SAFE_STOCK_6M / C.FO_COUNT_NUM_6M ELSE 0 END,0) AS FO_AVGASSET_6M
    ,ROUND(CASE WHEN C.FO_COUNT_NUM_12M != 0 THEN C.FO_AS_SAFE_STOCK_12M / C.FO_COUNT_NUM_12M ELSE 0 END,0) AS FO_AVGASSET_12M
FROM DS_SEC.CF_CUSTID A
LEFT JOIN TEMP6ASSET1 B
ON A.CUSTOMER_ID=B.CUSTOMER_ID
LEFT JOIN TEMP6ASSET2 C
ON A.CUSTOMER_ID=C.CUSTOMER_ID
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
INSERT INTO DS_SEC.CF_ASSET2
SELECT A.CUSTOMER_ID
    ,A.YYYYMM
    -- 一般股票
    ,ROUND(B.STGS_SAFE_STOCK_M,0) AS STGS_AVGASSET_M
    ,ROUND(CASE WHEN B.STGS_COUNT_NUM_3M != 0 THEN B.STGS_AS_ASSET_3M / B.STGS_COUNT_NUM_3M ELSE 0 END,0) AS STGS_AVGASSET_3M
    ,ROUND(CASE WHEN B.STGS_COUNT_NUM_6M != 0 THEN B.STGS_AS_ASSET_6M / B.STGS_COUNT_NUM_6M ELSE 0 END,0) AS STGS_AVGASSET_6M
    ,ROUND(CASE WHEN B.STGS_COUNT_NUM_12M != 0 THEN B.STGS_AS_ASSET_12M / B.STGS_COUNT_NUM_12M ELSE 0 END,0) AS STGS_AVGASSET_12M
    ,ROUND(B.STGS_SAFE_STOCK_M,0) AS STGS_ASSET_M
    ,ROUND(B.STGS_SAFE_STOCK_M - B.STGS_SAFE_STOCK_L,0) AS STGS_ASSET_M_MDIFF
    ,ROUND(B.STGS_SAFE_STOCK_M - B.STGS_SAFE_STOCK_3M,0) AS STGS_ASSET_3M_MDIFF
    ,ROUND(B.STGS_SAFE_STOCK_M - B.STGS_SAFE_STOCK_6M,0) AS STGS_ASSET_6M_MDIFF
    ,ROUND(B.STGS_SAFE_STOCK_M - B.STGS_SAFE_STOCK_12M,0) AS STGS_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.STGS_SAFE_STOCK_L !=0 THEN (B.STGS_SAFE_STOCK_M / B.STGS_SAFE_STOCK_L)-1 ELSE 0 END,4) AS STGS_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.STGS_SAFE_STOCK_3M !=0 THEN (B.STGS_SAFE_STOCK_M / B.STGS_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS STGS_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.STGS_SAFE_STOCK_6M !=0 THEN (B.STGS_SAFE_STOCK_M / B.STGS_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS STGS_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.STGS_SAFE_STOCK_12M !=0 THEN (B.STGS_SAFE_STOCK_M / B.STGS_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS STGS_ASSET_12M_RDIFF
    
    -- 股票ETF
    ,ROUND(B.STETF_SAFE_STOCK_M,0) AS STETF_AVGASSET_M
    ,ROUND(CASE WHEN B.STETF_COUNT_NUM_3M != 0 THEN B.STETF_AS_ASSET_3M / B.STETF_COUNT_NUM_3M ELSE 0 END,0) AS STETF_AVGASSET_3M
    ,ROUND(CASE WHEN B.STETF_COUNT_NUM_6M != 0 THEN B.STETF_AS_ASSET_6M / B.STETF_COUNT_NUM_6M ELSE 0 END,0) AS STETF_AVGASSET_6M
    ,ROUND(CASE WHEN B.STETF_COUNT_NUM_12M != 0 THEN B.STETF_AS_ASSET_12M / B.STETF_COUNT_NUM_12M ELSE 0 END,0) AS STETF_AVGASSET_12M
    ,ROUND(B.STETF_SAFE_STOCK_M,0) AS STETF_ASSET_M
    ,ROUND(B.STETF_SAFE_STOCK_M - B.STETF_SAFE_STOCK_L,0) AS STETF_ASSET_M_MDIFF
    ,ROUND(B.STETF_SAFE_STOCK_M - B.STETF_SAFE_STOCK_3M,0) AS STETF_ASSET_3M_MDIFF
    ,ROUND(B.STETF_SAFE_STOCK_M - B.STETF_SAFE_STOCK_6M,0) AS STETF_ASSET_6M_MDIFF
    ,ROUND(B.STETF_SAFE_STOCK_M - B.STETF_SAFE_STOCK_12M,0) AS STETF_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.STETF_SAFE_STOCK_L != 0 THEN (B.STETF_SAFE_STOCK_M / B.STETF_SAFE_STOCK_L)-1 ELSE 0 END,4) AS STETF_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.STETF_SAFE_STOCK_3M != 0 THEN (B.STETF_SAFE_STOCK_M / B.STETF_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS STETF_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.STETF_SAFE_STOCK_6M != 0 THEN (B.STETF_SAFE_STOCK_M / B.STETF_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS STETF_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.STETF_SAFE_STOCK_12M != 0 THEN (B.STETF_SAFE_STOCK_M / B.STETF_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS STETF_ASSET_12M_RDIFF
    
    -- 認股權證
    ,ROUND(B.STWA_SAFE_STOCK_M,0) AS STWA_AVGASSET_M
    ,ROUND(CASE WHEN B.STWA_COUNT_NUM_3M != 0 THEN B.STWA_AS_ASSET_3M / B.STWA_COUNT_NUM_3M ELSE 0 END,0) AS STWA_AVGASSET_3M
    ,ROUND(CASE WHEN B.STWA_COUNT_NUM_6M != 0 THEN B.STWA_AS_ASSET_6M / B.STWA_COUNT_NUM_6M ELSE 0 END,0) AS STWA_AVGASSET_6M
    ,ROUND(CASE WHEN B.STWA_COUNT_NUM_12M != 0 THEN B.STWA_AS_ASSET_12M / B.STWA_COUNT_NUM_12M ELSE 0 END,0) AS STWA_AVGASSET_12M
    ,ROUND(B.STWA_SAFE_STOCK_M,0) AS STWA_ASSET_M
    ,ROUND(B.STWA_SAFE_STOCK_M - B.STWA_SAFE_STOCK_L,0) AS STWA_ASSET_M_MDIFF
    ,ROUND(B.STWA_SAFE_STOCK_M - B.STWA_SAFE_STOCK_3M,0) AS STWA_ASSET_3M_MDIFF
    ,ROUND(B.STWA_SAFE_STOCK_M - B.STWA_SAFE_STOCK_6M,0) AS STWA_ASSET_6M_MDIFF
    ,ROUND(B.STWA_SAFE_STOCK_M - B.STWA_SAFE_STOCK_12M,0) AS STWA_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.STWA_SAFE_STOCK_L != 0 THEN (B.STWA_SAFE_STOCK_M / B.STWA_SAFE_STOCK_L)-1 ELSE 0 END,4) AS STWA_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.STWA_SAFE_STOCK_3M != 0 THEN (B.STWA_SAFE_STOCK_M / B.STWA_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS STWA_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.STWA_SAFE_STOCK_6M != 0 THEN (B.STWA_SAFE_STOCK_M / B.STWA_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS STWA_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.STWA_SAFE_STOCK_12M != 0 THEN (B.STWA_SAFE_STOCK_M / B.STWA_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS STWA_ASSET_12M_RDIFF
    
    -- 其他類股票
    ,ROUND(B.OST_SAFE_STOCK_M,0) AS OST_AVGASSET_M
    ,ROUND(CASE WHEN B.OST_COUNT_NUM_3M != 0 THEN B.OST_AS_ASSET_3M / B.OST_COUNT_NUM_3M ELSE 0 END,0) AS OST_AVGASSET_3M
    ,ROUND(CASE WHEN B.OST_COUNT_NUM_6M != 0 THEN B.OST_AS_ASSET_6M / B.OST_COUNT_NUM_6M ELSE 0 END,0) AS OST_AVGASSET_6M
    ,ROUND(CASE WHEN B.OST_COUNT_NUM_12M != 0 THEN B.OST_AS_ASSET_12M / B.OST_COUNT_NUM_12M ELSE 0 END,0) AS OST_AVGASSET_12M
    ,ROUND(B.OST_SAFE_STOCK_M,0) AS OST_ASSET_M
    ,ROUND(B.OST_SAFE_STOCK_M - B.OST_SAFE_STOCK_L,0) AS OST_ASSET_M_MDIFF
    ,ROUND(B.OST_SAFE_STOCK_M - B.OST_SAFE_STOCK_3M,0) AS OST_ASSET_3M_MDIFF
    ,ROUND(B.OST_SAFE_STOCK_M - B.OST_SAFE_STOCK_6M,0) AS OST_ASSET_6M_MDIFF
    ,ROUND(B.OST_SAFE_STOCK_M - B.OST_SAFE_STOCK_12M,0) AS OST_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.OST_SAFE_STOCK_L != 0 THEN (B.OST_SAFE_STOCK_M / B.OST_SAFE_STOCK_L)-1 ELSE 0 END,4) AS OST_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.OST_SAFE_STOCK_3M != 0 THEN (B.OST_SAFE_STOCK_M / B.OST_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS OST_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.OST_SAFE_STOCK_6M != 0 THEN (B.OST_SAFE_STOCK_M / B.OST_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS OST_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.OST_SAFE_STOCK_12M != 0 THEN (B.OST_SAFE_STOCK_M / B.OST_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS OST_ASSET_12M_RDIFF
    
    -- 公司債
    ,ROUND(B.FBC_SAFE_STOCK_M,0) AS FBC_AVGASSET_M
    ,ROUND(CASE WHEN B.FBC_COUNT_NUM_3M != 0 THEN B.FBC_AS_ASSET_3M / B.FBC_COUNT_NUM_3M ELSE 0 END,0) AS FBC_AVGASSET_3M
    ,ROUND(CASE WHEN B.FBC_COUNT_NUM_6M != 0 THEN B.FBC_AS_ASSET_6M / B.FBC_COUNT_NUM_6M ELSE 0 END,0) AS FBC_AVGASSET_6M
    ,ROUND(CASE WHEN B.FBC_COUNT_NUM_12M != 0 THEN B.FBC_AS_ASSET_12M / B.FBC_COUNT_NUM_12M ELSE 0 END,0) AS FBC_AVGASSET_12M
    ,ROUND(B.FBC_SAFE_STOCK_M,0) AS FBC_ASSET_M
    ,ROUND(B.FBC_SAFE_STOCK_M - B.FBC_SAFE_STOCK_L,0) AS FBC_ASSET_M_MDIFF
    ,ROUND(B.FBC_SAFE_STOCK_M - B.FBC_SAFE_STOCK_3M,0) AS FBC_ASSET_3M_MDIFF
    ,ROUND(B.FBC_SAFE_STOCK_M - B.FBC_SAFE_STOCK_6M,0) AS FBC_ASSET_6M_MDIFF
    ,ROUND(B.FBC_SAFE_STOCK_M - B.FBC_SAFE_STOCK_12M,0) AS FBC_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FBC_SAFE_STOCK_L != 0 THEN (B.FBC_SAFE_STOCK_M / B.FBC_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FBC_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FBC_SAFE_STOCK_3M != 0 THEN (B.FBC_SAFE_STOCK_M / B.FBC_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FBC_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FBC_SAFE_STOCK_6M != 0 THEN (B.FBC_SAFE_STOCK_M / B.FBC_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FBC_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FBC_SAFE_STOCK_12M != 0 THEN (B.FBC_SAFE_STOCK_M / B.FBC_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FBC_ASSET_12M_RDIFF
    
    -- 公債
    ,ROUND(B.FBG_SAFE_STOCK_M,0) AS FBG_AVGASSET_M
    ,ROUND(CASE WHEN B.FBG_COUNT_NUM_3M != 0 THEN B.FBG_AS_ASSET_3M / B.FBG_COUNT_NUM_3M ELSE 0 END,0) AS FBG_AVGASSET_3M
    ,ROUND(CASE WHEN B.FBG_COUNT_NUM_6M != 0 THEN B.FBG_AS_ASSET_6M / B.FBG_COUNT_NUM_6M ELSE 0 END,0) AS FBG_AVGASSET_6M
    ,ROUND(CASE WHEN B.FBG_COUNT_NUM_12M != 0 THEN B.FBG_AS_ASSET_12M / B.FBG_COUNT_NUM_12M ELSE 0 END,0) AS FBG_AVGASSET_12M
    ,ROUND(B.FBG_SAFE_STOCK_M,0) AS FBG_ASSET_M
    ,ROUND(B.FBG_SAFE_STOCK_M - B.FBG_SAFE_STOCK_L,0) AS FBG_ASSET_M_MDIFF
    ,ROUND(B.FBG_SAFE_STOCK_M - B.FBG_SAFE_STOCK_3M,0) AS FBG_ASSET_3M_MDIFF
    ,ROUND(B.FBG_SAFE_STOCK_M - B.FBG_SAFE_STOCK_6M,0) AS FBG_ASSET_6M_MDIFF
    ,ROUND(B.FBG_SAFE_STOCK_M - B.FBG_SAFE_STOCK_12M,0) AS FBG_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FBG_SAFE_STOCK_L != 0 THEN (B.FBG_SAFE_STOCK_M / B.FBG_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FBG_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FBG_SAFE_STOCK_3M != 0 THEN (B.FBG_SAFE_STOCK_M / B.FBG_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FBG_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FBG_SAFE_STOCK_6M != 0 THEN (B.FBG_SAFE_STOCK_M / B.FBG_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FBG_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FBG_SAFE_STOCK_12M != 0 THEN (B.FBG_SAFE_STOCK_M / B.FBG_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FBG_ASSET_12M_RDIFF
    
    -- 金融債
    ,ROUND(B.FBF_SAFE_STOCK_M,0) AS FBF_AVGASSET_M
    ,ROUND(CASE WHEN B.FBF_COUNT_NUM_3M != 0 THEN B.FBF_AS_ASSET_3M / B.FBF_COUNT_NUM_3M ELSE 0 END,0) AS FBF_AVGASSET_3M
    ,ROUND(CASE WHEN B.FBF_COUNT_NUM_6M != 0 THEN B.FBF_AS_ASSET_6M / B.FBF_COUNT_NUM_6M ELSE 0 END,0) AS FBF_AVGASSET_6M
    ,ROUND(CASE WHEN B.FBF_COUNT_NUM_12M != 0 THEN B.FBF_AS_ASSET_12M / B.FBF_COUNT_NUM_12M ELSE 0 END,0) AS FBF_AVGASSET_12M
    ,ROUND(B.FBF_SAFE_STOCK_M,0) AS FBF_ASSET_M
    ,ROUND(B.FBF_SAFE_STOCK_M - B.FBF_SAFE_STOCK_L,0) AS FBF_ASSET_M_MDIFF
    ,ROUND(B.FBF_SAFE_STOCK_M - B.FBF_SAFE_STOCK_3M,0) AS FBF_ASSET_3M_MDIFF
    ,ROUND(B.FBF_SAFE_STOCK_M - B.FBF_SAFE_STOCK_6M,0) AS FBF_ASSET_6M_MDIFF
    ,ROUND(B.FBF_SAFE_STOCK_M - B.FBF_SAFE_STOCK_12M,0) AS FBF_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FBF_SAFE_STOCK_L != 0 THEN (B.FBF_SAFE_STOCK_M / B.FBF_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FBF_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FBF_SAFE_STOCK_3M != 0 THEN (B.FBF_SAFE_STOCK_M / B.FBF_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FBF_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FBF_SAFE_STOCK_6M != 0 THEN (B.FBF_SAFE_STOCK_M / B.FBF_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FBF_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FBF_SAFE_STOCK_12M != 0 THEN (B.FBF_SAFE_STOCK_M / B.FBF_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FBF_ASSET_12M_RDIFF
    
    -- 其他海外債
    ,ROUND(B.OFB_SAFE_STOCK_M,0) AS OFB_AVGASSET_M
    ,ROUND(CASE WHEN B.OFB_COUNT_NUM_3M != 0 THEN B.OFB_AS_ASSET_3M / B.OFB_COUNT_NUM_3M ELSE 0 END,0) AS OFB_AVGASSET_3M
    ,ROUND(CASE WHEN B.OFB_COUNT_NUM_6M != 0 THEN B.OFB_AS_ASSET_6M / B.OFB_COUNT_NUM_6M ELSE 0 END,0) AS OFB_AVGASSET_6M
    ,ROUND(CASE WHEN B.OFB_COUNT_NUM_12M != 0 THEN B.OFB_AS_ASSET_12M / B.OFB_COUNT_NUM_12M ELSE 0 END,0) AS OFB_AVGASSET_12M
    ,ROUND(B.OFB_SAFE_STOCK_M,0) AS OFB_ASSET_M
    ,ROUND(B.OFB_SAFE_STOCK_M - B.OFB_SAFE_STOCK_L,0) AS OFB_ASSET_M_MDIFF
    ,ROUND(B.OFB_SAFE_STOCK_M - B.OFB_SAFE_STOCK_3M,0) AS OFB_ASSET_3M_MDIFF
    ,ROUND(B.OFB_SAFE_STOCK_M - B.OFB_SAFE_STOCK_6M,0) AS OFB_ASSET_6M_MDIFF
    ,ROUND(B.OFB_SAFE_STOCK_M - B.OFB_SAFE_STOCK_12M,0) AS OFB_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.OFB_SAFE_STOCK_L != 0 THEN (B.OFB_SAFE_STOCK_M / B.OFB_SAFE_STOCK_L)-1 ELSE 0 END,4) AS OFB_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.OFB_SAFE_STOCK_3M != 0 THEN (B.OFB_SAFE_STOCK_M / B.OFB_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS OFB_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.OFB_SAFE_STOCK_6M != 0 THEN (B.OFB_SAFE_STOCK_M / B.OFB_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS OFB_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.OFB_SAFE_STOCK_12M != 0 THEN (B.OFB_SAFE_STOCK_M / B.OFB_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS OFB_ASSET_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN TEMP6ASSET1 B
ON A.CUSTOMER_ID=B.CUSTOMER_ID
LEFT JOIN TEMP6ASSET2 C
ON A.CUSTOMER_ID=C.CUSTOMER_ID
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
INSERT INTO DS_SEC.CF_ASSET3
SELECT A.CUSTOMER_ID
    ,A.YYYYMM
    -- 平衡型及多重資產型基金
    ,ROUND(B.FDBA_SAFE_STOCK_M,0) AS FDBA_AVGASSET_M
    ,ROUND(CASE WHEN B.FDBA_COUNT_NUM_3M != 0 THEN B.FDBA_AS_ASSET_3M / B.FDBA_COUNT_NUM_3M ELSE 0 END,0) AS FDBA_AVGASSET_3M
    ,ROUND(CASE WHEN B.FDBA_COUNT_NUM_6M != 0 THEN B.FDBA_AS_ASSET_6M / B.FDBA_COUNT_NUM_6M ELSE 0 END,0) AS FDBA_AVGASSET_6M
    ,ROUND(CASE WHEN B.FDBA_COUNT_NUM_12M != 0 THEN B.FDBA_AS_ASSET_12M / B.FDBA_COUNT_NUM_12M ELSE 0 END,0) AS FDBA_AVGASSET_12M
    ,ROUND(B.FDBA_SAFE_STOCK_M,0) AS FDBA_ASSET_M
    ,ROUND(B.FDBA_SAFE_STOCK_M - B.FDBA_SAFE_STOCK_L,0) AS FDBA_ASSET_M_MDIFF
    ,ROUND(B.FDBA_SAFE_STOCK_M - B.FDBA_SAFE_STOCK_3M,0) AS FDBA_ASSET_3M_MDIFF
    ,ROUND(B.FDBA_SAFE_STOCK_M - B.FDBA_SAFE_STOCK_6M,0) AS FDBA_ASSET_6M_MDIFF
    ,ROUND(B.FDBA_SAFE_STOCK_M - B.FDBA_SAFE_STOCK_12M,0) AS FDBA_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FDBA_SAFE_STOCK_L != 0 THEN (B.FDBA_SAFE_STOCK_M / B.FDBA_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FDBA_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FDBA_SAFE_STOCK_3M != 0 THEN (B.FDBA_SAFE_STOCK_M / B.FDBA_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FDBA_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FDBA_SAFE_STOCK_6M != 0 THEN (B.FDBA_SAFE_STOCK_M / B.FDBA_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FDBA_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FDBA_SAFE_STOCK_12M != 0 THEN (B.FDBA_SAFE_STOCK_M / B.FDBA_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FDBA_ASSET_12M_RDIFF
    
    -- 股票型基金
    ,ROUND(B.FDST_SAFE_STOCK_M,0) AS FDST_AVGASSET_M
    ,ROUND(CASE WHEN B.FDST_COUNT_NUM_3M != 0 THEN B.FDST_AS_ASSET_3M / B.FDST_COUNT_NUM_3M ELSE 0 END,0) AS FDST_AVGASSET_3M
    ,ROUND(CASE WHEN B.FDST_COUNT_NUM_6M != 0 THEN B.FDST_AS_ASSET_6M / B.FDST_COUNT_NUM_6M ELSE 0 END,0) AS FDST_AVGASSET_6M
    ,ROUND(CASE WHEN B.FDST_COUNT_NUM_12M != 0 THEN B.FDST_AS_ASSET_12M / B.FDST_COUNT_NUM_12M ELSE 0 END,0) AS FDST_AVGASSET_12M
    ,ROUND(B.FDST_SAFE_STOCK_M,0) AS FDST_ASSET_M
    ,ROUND(B.FDST_SAFE_STOCK_M - B.FDST_SAFE_STOCK_L,0) AS FDST_ASSET_M_MDIFF
    ,ROUND(B.FDST_SAFE_STOCK_M - B.FDST_SAFE_STOCK_3M,0) AS FDST_ASSET_3M_MDIFF
    ,ROUND(B.FDST_SAFE_STOCK_M - B.FDST_SAFE_STOCK_6M,0) AS FDST_ASSET_6M_MDIFF
    ,ROUND(B.FDST_SAFE_STOCK_M - B.FDST_SAFE_STOCK_12M,0) AS FDST_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FDST_SAFE_STOCK_L != 0 THEN (B.FDST_SAFE_STOCK_M / B.FDST_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FDST_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FDST_SAFE_STOCK_3M != 0 THEN (B.FDST_SAFE_STOCK_M / B.FDST_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FDST_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FDST_SAFE_STOCK_6M != 0 THEN (B.FDST_SAFE_STOCK_M / B.FDST_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FDST_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FDST_SAFE_STOCK_12M != 0 THEN (B.FDST_SAFE_STOCK_M / B.FDST_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FDST_ASSET_12M_RDIFF
    
    -- 貨幣型基金
    ,ROUND(B.FDCU_SAFE_STOCK_M,0) AS FDCU_AVGASSET_M
    ,ROUND(CASE WHEN B.FDCU_COUNT_NUM_3M != 0 THEN B.FDCU_AS_ASSET_3M / B.FDCU_COUNT_NUM_3M ELSE 0 END,0) AS FDCU_AVGASSET_3M
    ,ROUND(CASE WHEN B.FDCU_COUNT_NUM_6M != 0 THEN B.FDCU_AS_ASSET_6M / B.FDCU_COUNT_NUM_6M ELSE 0 END,0) AS FDCU_AVGASSET_6M
    ,ROUND(CASE WHEN B.FDCU_COUNT_NUM_12M != 0 THEN B.FDCU_AS_ASSET_12M / B.FDCU_COUNT_NUM_12M ELSE 0 END,0) AS FDCU_AVGASSET_12M
    ,ROUND(B.FDCU_SAFE_STOCK_M,0) AS FDCU_ASSET_M
    ,ROUND(B.FDCU_SAFE_STOCK_M - B.FDCU_SAFE_STOCK_L,0) AS FDCU_ASSET_M_MDIFF
    ,ROUND(B.FDCU_SAFE_STOCK_M - B.FDCU_SAFE_STOCK_3M,0) AS FDCU_ASSET_3M_MDIFF
    ,ROUND(B.FDCU_SAFE_STOCK_M - B.FDCU_SAFE_STOCK_6M,0) AS FDCU_ASSET_6M_MDIFF
    ,ROUND(B.FDCU_SAFE_STOCK_M - B.FDCU_SAFE_STOCK_12M,0) AS FDCU_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FDCU_SAFE_STOCK_L != 0 THEN (B.FDCU_SAFE_STOCK_M / B.FDCU_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FDCU_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FDCU_SAFE_STOCK_3M != 0 THEN (B.FDCU_SAFE_STOCK_M / B.FDCU_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FDCU_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FDCU_SAFE_STOCK_6M != 0 THEN (B.FDCU_SAFE_STOCK_M / B.FDCU_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FDCU_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FDCU_SAFE_STOCK_12M != 0 THEN (B.FDCU_SAFE_STOCK_M / B.FDCU_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FDCU_ASSET_12M_RDIFF
    
    -- 債券型基金
    ,ROUND(B.FDB_SAFE_STOCK_M,0) AS FDB_AVGASSET_M
    ,ROUND(CASE WHEN B.FDB_COUNT_NUM_3M != 0 THEN B.FDB_AS_ASSET_3M / B.FDB_COUNT_NUM_3M ELSE 0 END,0) AS FDB_AVGASSET_3M
    ,ROUND(CASE WHEN B.FDB_COUNT_NUM_6M != 0 THEN B.FDB_AS_ASSET_6M / B.FDB_COUNT_NUM_6M ELSE 0 END,0) AS FDB_AVGASSET_6M
    ,ROUND(CASE WHEN B.FDB_COUNT_NUM_12M != 0 THEN B.FDB_AS_ASSET_12M / B.FDB_COUNT_NUM_12M ELSE 0 END,0) AS FDB_AVGASSET_12M
    ,ROUND(B.FDB_SAFE_STOCK_M,0) AS FDB_ASSET_M
    ,ROUND(B.FDB_SAFE_STOCK_M - B.FDB_SAFE_STOCK_L,0) AS FDB_ASSET_M_MDIFF
    ,ROUND(B.FDB_SAFE_STOCK_M - B.FDB_SAFE_STOCK_3M,0) AS FDB_ASSET_3M_MDIFF
    ,ROUND(B.FDB_SAFE_STOCK_M - B.FDB_SAFE_STOCK_6M,0) AS FDB_ASSET_6M_MDIFF
    ,ROUND(B.FDB_SAFE_STOCK_M - B.FDB_SAFE_STOCK_12M,0) AS FDB_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FDB_SAFE_STOCK_L != 0 THEN (B.FDB_SAFE_STOCK_M / B.FDB_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FDB_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FDB_SAFE_STOCK_3M != 0 THEN (B.FDB_SAFE_STOCK_M / B.FDB_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FDB_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FDB_SAFE_STOCK_6M != 0 THEN (B.FDB_SAFE_STOCK_M / B.FDB_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FDB_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FDB_SAFE_STOCK_12M != 0 THEN (B.FDB_SAFE_STOCK_M / B.FDB_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FDB_ASSET_12M_RDIFF
    
    -- 其他型基金
    ,ROUND(B.OFD_SAFE_STOCK_M,0) AS OFD_AVGASSET_M
    ,ROUND(CASE WHEN B.OFD_COUNT_NUM_3M != 0 THEN B.OFD_AS_ASSET_3M / B.OFD_COUNT_NUM_3M ELSE 0 END,0) AS OFD_AVGASSET_3M
    ,ROUND(CASE WHEN B.OFD_COUNT_NUM_6M != 0 THEN B.OFD_AS_ASSET_6M / B.OFD_COUNT_NUM_6M ELSE 0 END,0) AS OFD_AVGASSET_6M
    ,ROUND(CASE WHEN B.OFD_COUNT_NUM_12M != 0 THEN B.OFD_AS_ASSET_12M / B.OFD_COUNT_NUM_12M ELSE 0 END,0) AS OFD_AVGASSET_12M
    ,ROUND(B.OFD_SAFE_STOCK_M,0) AS OFD_ASSET_M
    ,ROUND(B.OFD_SAFE_STOCK_M - B.OFD_SAFE_STOCK_L,0) AS OFD_ASSET_M_MDIFF
    ,ROUND(B.OFD_SAFE_STOCK_M - B.OFD_SAFE_STOCK_3M,0) AS OFD_ASSET_3M_MDIFF
    ,ROUND(B.OFD_SAFE_STOCK_M - B.OFD_SAFE_STOCK_6M,0) AS OFD_ASSET_6M_MDIFF
    ,ROUND(B.OFD_SAFE_STOCK_M - B.OFD_SAFE_STOCK_12M,0) AS OFD_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.OFD_SAFE_STOCK_L != 0 THEN (B.OFD_SAFE_STOCK_M / B.OFD_SAFE_STOCK_L)-1 ELSE 0 END,4) AS OFD_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.OFD_SAFE_STOCK_3M != 0 THEN (B.OFD_SAFE_STOCK_M / B.OFD_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS OFD_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.OFD_SAFE_STOCK_6M != 0 THEN (B.OFD_SAFE_STOCK_M / B.OFD_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS OFD_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.OFD_SAFE_STOCK_12M != 0 THEN (B.OFD_SAFE_STOCK_M / B.OFD_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS OFD_ASSET_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN TEMP6ASSET1 B
ON A.CUSTOMER_ID=B.CUSTOMER_ID
LEFT JOIN TEMP6ASSET2 C
ON A.CUSTOMER_ID=C.CUSTOMER_ID
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
INSERT INTO DS_SEC.CF_ASSET4
SELECT A.CUSTOMER_ID
    ,A.YYYYMM
    -- 內期
    ,ROUND(CASE WHEN C.UFC_COUNT_NUM_M != 0 THEN C.UFC_AS_ASSET_M / C.UFC_COUNT_NUM_M ELSE 0 END,0) AS UFC_AVGASSET_M
    ,ROUND(CASE WHEN C.UFC_COUNT_NUM_3M != 0 THEN C.UFC_AS_ASSET_3M / C.UFC_COUNT_NUM_3M ELSE 0 END,0) AS UFC_AVGASSET_3M
    ,ROUND(CASE WHEN C.UFC_COUNT_NUM_6M != 0 THEN C.UFC_AS_ASSET_6M / C.UFC_COUNT_NUM_6M ELSE 0 END,0) AS UFC_AVGASSET_6M
    ,ROUND(CASE WHEN C.UFC_COUNT_NUM_12M != 0 THEN C.UFC_AS_ASSET_12M / C.UFC_COUNT_NUM_12M ELSE 0 END,0) AS UFC_AVGASSET_12M
    ,ROUND(B.UFC_SAFE_STOCK_M,0) AS UFC_ASSET_M
    ,ROUND(B.UFC_SAFE_STOCK_M - B.UFC_SAFE_STOCK_L,0) AS UFC_ASSET_M_MDIFF
    ,ROUND(B.UFC_SAFE_STOCK_M - B.UFC_SAFE_STOCK_3M,0) AS UFC_ASSET_3M_MDIFF
    ,ROUND(B.UFC_SAFE_STOCK_M - B.UFC_SAFE_STOCK_6M,0) AS UFC_ASSET_6M_MDIFF
    ,ROUND(B.UFC_SAFE_STOCK_M - B.UFC_SAFE_STOCK_12M,0) AS UFC_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.UFC_SAFE_STOCK_L != 0 THEN (B.UFC_SAFE_STOCK_M / B.UFC_SAFE_STOCK_L)-1 ELSE 0 END,4) AS UFC_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.UFC_SAFE_STOCK_3M != 0 THEN (B.UFC_SAFE_STOCK_M / B.UFC_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS UFC_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.UFC_SAFE_STOCK_6M != 0 THEN (B.UFC_SAFE_STOCK_M / B.UFC_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS UFC_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.UFC_SAFE_STOCK_12M != 0 THEN (B.UFC_SAFE_STOCK_M / B.UFC_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS UFC_ASSET_12M_RDIFF
    
    -- 外期
    ,ROUND(CASE WHEN C.UFF_COUNT_NUM_M != 0 THEN C.UFF_AS_ASSET_M / C.UFF_COUNT_NUM_M ELSE 0 END,0) AS UFF_AVGASSET_M
    ,ROUND(CASE WHEN C.UFF_COUNT_NUM_3M != 0 THEN C.UFF_AS_ASSET_3M / C.UFF_COUNT_NUM_3M ELSE 0 END,0) AS UFF_AVGASSET_3M
    ,ROUND(CASE WHEN C.UFF_COUNT_NUM_6M != 0 THEN C.UFF_AS_ASSET_6M / C.UFF_COUNT_NUM_6M ELSE 0 END,0) AS UFF_AVGASSET_6M
    ,ROUND(CASE WHEN C.UFF_COUNT_NUM_12M != 0 THEN C.UFF_AS_ASSET_12M / C.UFF_COUNT_NUM_12M ELSE 0 END,0) AS UFF_AVGASSET_12M
    ,ROUND(B.UFF_SAFE_STOCK_M,0) AS UFF_ASSET_M
    ,ROUND(B.UFF_SAFE_STOCK_M - B.UFF_SAFE_STOCK_L,0) AS UFF_ASSET_M_MDIFF
    ,ROUND(B.UFF_SAFE_STOCK_M - B.UFF_SAFE_STOCK_3M,0) AS UFF_ASSET_3M_MDIFF
    ,ROUND(B.UFF_SAFE_STOCK_M - B.UFF_SAFE_STOCK_6M,0) AS UFF_ASSET_6M_MDIFF
    ,ROUND(B.UFF_SAFE_STOCK_M - B.UFF_SAFE_STOCK_12M,0) AS UFF_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.UFF_SAFE_STOCK_L != 0 THEN (B.UFF_SAFE_STOCK_M / B.UFF_SAFE_STOCK_L)-1 ELSE 0 END,4) AS UFF_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.UFF_SAFE_STOCK_3M != 0 THEN (B.UFF_SAFE_STOCK_M / B.UFF_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS UFF_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.UFF_SAFE_STOCK_6M != 0 THEN (B.UFF_SAFE_STOCK_M / B.UFF_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS UFF_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.UFF_SAFE_STOCK_12M != 0 THEN (B.UFF_SAFE_STOCK_M / B.UFF_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS UFF_ASSET_12M_RDIFF
    
    -- 境內結構型
    ,ROUND(CASE WHEN C.NSN_COUNT_NUM_M != 0 THEN C.NSN_AS_ASSET_M / C.NSN_COUNT_NUM_M ELSE 0 END,0) AS NSN_AVGASSET_M
    ,ROUND(CASE WHEN C.NSN_COUNT_NUM_3M != 0 THEN C.NSN_AS_ASSET_3M / C.NSN_COUNT_NUM_3M ELSE 0 END,0) AS NSN_AVGASSET_3M
    ,ROUND(CASE WHEN C.NSN_COUNT_NUM_6M != 0 THEN C.NSN_AS_ASSET_6M / C.NSN_COUNT_NUM_6M ELSE 0 END,0) AS NSN_AVGASSET_6M
    ,ROUND(CASE WHEN C.NSN_COUNT_NUM_12M != 0 THEN C.NSN_AS_ASSET_12M / C.NSN_COUNT_NUM_12M ELSE 0 END,0) AS NSN_AVGASSET_12M
    ,ROUND(B.NSN_SAFE_STOCK_M,0) AS NSN_ASSET_M
    ,ROUND(B.NSN_SAFE_STOCK_M - B.NSN_SAFE_STOCK_L,0) AS NSN_ASSET_M_MDIFF
    ,ROUND(B.NSN_SAFE_STOCK_M - B.NSN_SAFE_STOCK_3M,0) AS NSN_ASSET_3M_MDIFF
    ,ROUND(B.NSN_SAFE_STOCK_M - B.NSN_SAFE_STOCK_6M,0) AS NSN_ASSET_6M_MDIFF
    ,ROUND(B.NSN_SAFE_STOCK_M - B.NSN_SAFE_STOCK_12M,0) AS NSN_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.NSN_SAFE_STOCK_L != 0 THEN (B.NSN_SAFE_STOCK_M / B.NSN_SAFE_STOCK_L)-1 ELSE 0 END,4) AS NSN_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.NSN_SAFE_STOCK_3M != 0 THEN (B.NSN_SAFE_STOCK_M / B.NSN_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS NSN_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.NSN_SAFE_STOCK_6M != 0 THEN (B.NSN_SAFE_STOCK_M / B.NSN_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS NSN_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.NSN_SAFE_STOCK_12M != 0 THEN (B.NSN_SAFE_STOCK_M / B.NSN_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS NSN_ASSET_12M_RDIFF
    
    -- 境外結構型
    ,ROUND(CASE WHEN C.FSN_COUNT_NUM_M != 0 THEN C.FSN_AS_ASSET_M / C.FSN_COUNT_NUM_M ELSE 0 END,0) AS FSN_AVGASSET_M
    ,ROUND(CASE WHEN C.FSN_COUNT_NUM_3M != 0 THEN C.FSN_AS_ASSET_3M / C.FSN_COUNT_NUM_3M ELSE 0 END,0) AS FSN_AVGASSET_3M
    ,ROUND(CASE WHEN C.FSN_COUNT_NUM_6M != 0 THEN C.FSN_AS_ASSET_6M / C.FSN_COUNT_NUM_6M ELSE 0 END,0) AS FSN_AVGASSET_6M
    ,ROUND(CASE WHEN C.FSN_COUNT_NUM_12M != 0 THEN C.FSN_AS_ASSET_12M / C.FSN_COUNT_NUM_12M ELSE 0 END,0) AS FSN_AVGASSET_12M
    ,ROUND(B.FSN_SAFE_STOCK_M,0) AS FSN_ASSET_M
    ,ROUND(B.FSN_SAFE_STOCK_M - B.FSN_SAFE_STOCK_L,0) AS FSN_ASSET_M_MDIFF
    ,ROUND(B.FSN_SAFE_STOCK_M - B.FSN_SAFE_STOCK_3M,0) AS FSN_ASSET_3M_MDIFF
    ,ROUND(B.FSN_SAFE_STOCK_M - B.FSN_SAFE_STOCK_6M,0) AS FSN_ASSET_6M_MDIFF
    ,ROUND(B.FSN_SAFE_STOCK_M - B.FSN_SAFE_STOCK_12M,0) AS FSN_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.FSN_SAFE_STOCK_L != 0 THEN (B.FSN_SAFE_STOCK_M / B.FSN_SAFE_STOCK_L)-1 ELSE 0 END,4) AS FSN_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.FSN_SAFE_STOCK_3M != 0 THEN (B.FSN_SAFE_STOCK_M / B.FSN_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS FSN_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.FSN_SAFE_STOCK_6M != 0 THEN (B.FSN_SAFE_STOCK_M / B.FSN_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS FSN_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.FSN_SAFE_STOCK_12M != 0 THEN (B.FSN_SAFE_STOCK_M / B.FSN_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS FSN_ASSET_12M_RDIFF
    
    -- 選擇權
    ,ROUND(CASE WHEN C.OP_COUNT_NUM_M != 0 THEN C.OP_AS_ASSET_M / C.OP_COUNT_NUM_M ELSE 0 END,0) AS OP_AVGASSET_M
    ,ROUND(CASE WHEN C.OP_COUNT_NUM_3M != 0 THEN C.OP_AS_ASSET_3M / C.OP_COUNT_NUM_3M ELSE 0 END) AS OP_AVGASSET_3M
    ,ROUND(CASE WHEN C.OP_COUNT_NUM_6M != 0 THEN C.OP_AS_ASSET_6M / C.OP_COUNT_NUM_6M ELSE 0 END,0) AS OP_AVGASSET_6M
    ,ROUND(CASE WHEN C.OP_COUNT_NUM_12M != 0 THEN C.OP_AS_ASSET_12M / C.OP_COUNT_NUM_12M ELSE 0 END,0) AS OP_AVGASSET_12M
    ,ROUND(B.OP_SAFE_STOCK_M,0) AS OP_ASSET_M
    ,ROUND(B.OP_SAFE_STOCK_M - B.OP_SAFE_STOCK_L,0) AS OP_ASSET_M_MDIFF
    ,ROUND(B.OP_SAFE_STOCK_M - B.OP_SAFE_STOCK_3M,0) AS OP_ASSET_3M_MDIFF
    ,ROUND(B.OP_SAFE_STOCK_M - B.OP_SAFE_STOCK_6M,0) AS OP_ASSET_6M_MDIFF
    ,ROUND(B.OP_SAFE_STOCK_M - B.OP_SAFE_STOCK_12M,0) AS OP_ASSET_12M_MDIFF
    ,ROUND(CASE WHEN B.OP_SAFE_STOCK_L != 0 THEN (B.OP_SAFE_STOCK_M / B.OP_SAFE_STOCK_L)-1 ELSE 0 END,4) AS OP_ASSET_M_RDIFF
    ,ROUND(CASE WHEN B.OP_SAFE_STOCK_3M != 0 THEN (B.OP_SAFE_STOCK_M / B.OP_SAFE_STOCK_3M)-1 ELSE 0 END,4) AS OP_ASSET_3M_RDIFF
    ,ROUND(CASE WHEN B.OP_SAFE_STOCK_6M != 0 THEN (B.OP_SAFE_STOCK_M / B.OP_SAFE_STOCK_6M)-1 ELSE 0 END,4) AS OP_ASSET_6M_RDIFF
    ,ROUND(CASE WHEN B.OP_SAFE_STOCK_12M != 0 THEN (B.OP_SAFE_STOCK_M / B.OP_SAFE_STOCK_12M)-1 ELSE 0 END,4) AS OP_ASSET_12M_RDIFF
FROM DS_SEC.CF_CUSTID A
LEFT JOIN TEMP6ASSET1 B
ON A.CUSTOMER_ID=B.CUSTOMER_ID
LEFT JOIN TEMP6ASSET2 C
ON A.CUSTOMER_ID=C.CUSTOMER_ID
WHERE A.YYYYMM = :ym
ORDER BY A.CUSTOMER_ID;
DROP TABLE TEMP6ASSET1 PURGE;
DROP TABLE TEMP6ASSET2 PURGE;
